// Proven by construction rather than by measurement — the two template literals
// cannot produce the same string — and pinned by report-settings.spec.js, which
// fails if either caller stops going through here.
function feedCacheKey(orgSlug, reportType, paramStr) {
  return `${orgSlug}:${reportType}:v${FEED_VERSION[reportType] || 1}:${paramStr || ""}`;
}
const REPORT_CACHE_TTL = {
  facility: 4 * 60 * 60 * 1000,            // 4 hrs — warmed at 5am
  gl: 15 * 60 * 1000,                     // 15 min — financials need to be near-live; the GL report also shows a "Data as of · Refresh" stamp for on-demand realtime
  roster: 2 * 60 * 60 * 1000,             // 2 hrs — enrollments change
  programs: 4 * 60 * 60 * 1000,           // 4 hrs
  memberships: 4 * 60 * 60 * 1000,        // 4 hrs
  products: 4 * 60 * 60 * 1000,           // 4 hrs
  fasttrack: 6 * 60 * 60 * 1000,          // 6 hrs — very stable
  waitlist: 6 * 60 * 60 * 1000,           // 6 hrs — demand shifts slowly
  "court-utilization": 6 * 60 * 60 * 1000, // 6 hrs
  "program-demographics": 6 * 60 * 60 * 1000, // 6 hrs
  calendar: 2 * 60 * 60 * 1000,           // 2 hrs — schedule changes
  historic: 6 * 60 * 60 * 1000,           // 6 hrs — rarely changes
  "instructor-payout": 4 * 60 * 60 * 1000, // 4 hrs
  "section-detail": 60 * 60 * 1000,       // 1 hr — drill-down still relatively fresh
  selfservice: 4 * 60 * 60 * 1000,        // 4 hrs — channel mix moves slowly
};
// Fully-historical windows (end_date before today) barely change — refunds and
// edits can back-modify them, but the nightly prewarm catches that drift.
// Serving them for 24h means prior-period delta fetches rarely hit Metabase twice.
const HIST_CACHE_TTL = 24 * 60 * 60 * 1000;
const dataCache = new Map();

// ── Adaptive cache governor ────────────────────────────────────────────
// Keeps resident memory bounded and biased toward reports people actually
// open. Big report payloads (e.g. full user exports) are the memory hogs but
// are rarely the hot path, so by default they are NOT held resident — they
// live on the disk cache (cheap on Railway) and are served from there. Any
// report that starts getting opened often is *learned* to be hot, pinned in
// memory, and kept fresh by prewarm. Set CACHE_ADAPTIVE=0 to disable and fall
// back to the previous "keep everything resident" behavior.
const CACHE_ADAPTIVE     = process.env.CACHE_ADAPTIVE !== "0";
const MAX_MEMORY_ENTRIES = Number(process.env.CACHE_MAX_MEMORY_ENTRIES || 300);
const HEAVY_ENTRY_BYTES  = Number(process.env.CACHE_HEAVY_BYTES || 1500000); // ~1.5 MB serialized
const HOT_WINDOW_MS      = Number(process.env.CACHE_HOT_WINDOW_MS || 7 * 24 * 60 * 60 * 1000);
const HOT_MIN_HITS       = Number(process.env.CACHE_HOT_MIN_HITS || 3); // opens within window ⇒ "hot"
// Small, high-traffic reports we always keep warm for every configured org.
const ALWAYS_WARM_REPORTS = new Set(["calendar", "gl", "facility"]);
// Large extracts we never prewarm or hold resident unless they're learned-hot.
const HEAVY_REPORTS       = new Set(["users", "ice-calendar"]);

// baseKey "slug:rt" → recent user-open timestamps (rolling HOT_WINDOW_MS).
const accessLog = new Map();
let _accessDirty = false;
const cacheBaseKey = (orgSlug, reportType) => `${orgSlug}:${reportType}`;

// Record a user-initiated report open. NOT called from prewarm/health probes,
// so learned popularity reflects real usage only.
function recordAccess(orgSlug, reportType) {
  if (!CACHE_ADAPTIVE || !orgSlug || !reportType) return;
  const bk = cacheBaseKey(orgSlug, reportType);
  const now = Date.now();
  const arr = (accessLog.get(bk) || []).filter(ts => now - ts < HOT_WINDOW_MS);
  arr.push(now);
  accessLog.set(bk, arr);
  _accessDirty = true;
}

// Opened often enough recently to be worth keeping warm/pinned?
function isReportHot(orgSlug, reportType) {
  const arr = accessLog.get(cacheBaseKey(orgSlug, reportType));
  if (!arr || !arr.length) return false;
  const now = Date.now();
  let n = 0;
  for (const ts of arr) if (now - ts < HOT_WINDOW_MS) n++;
  return n >= HOT_MIN_HITS;
}

// Should this (org, report) be prewarmed and held resident?
function isWarmTarget(orgSlug, reportType) {
  if (!CACHE_ADAPTIVE) return true;
  if (ALWAYS_WARM_REPORTS.has(reportType)) return true;
  if (HEAVY_REPORTS.has(reportType)) return isReportHot(orgSlug, reportType);
  return true; // light reports are cheap — keep warming them
}

// A resident entry is "pinned" (never LRU-evicted) if it's always-warm or
// learned-hot. Light-but-cold reports stay evictable — under memory pressure
// they fall to the disk cache (L2), which still serves them fast.
function isPinnedKey(key) {
  const parts = key.split(":");
  return ALWAYS_WARM_REPORTS.has(parts[1]) || isReportHot(parts[0], parts[1]);
}

// Evict least-recently-used, non-pinned entries until under the cap. Evicted
// entries remain on the disk cache, so they're still served fast (L2).
function enforceMemoryCap() {
  if (!CACHE_ADAPTIVE || dataCache.size <= MAX_MEMORY_ENTRIES) return;
  const evictable = [];
  for (const [k, v] of dataCache) {
    if (isPinnedKey(k)) continue;
    evictable.push([k, v.lastRead || v.ts]);
  }
  evictable.sort((a, b) => a[1] - b[1]); // oldest-touched first
  let i = 0;
  while (dataCache.size > MAX_MEMORY_ENTRIES && i < evictable.length) {
    dataCache.delete(evictable[i++][0]);
  }
}

// L2: read an entry straight from the disk cache (fast local read) when it's
// not resident in memory. Repopulates memory only for warm targets, so a big
// cold report opened once doesn't re-bloat RAM.
// Disk-cache filename for a cache key. Hash the FULL key — do NOT truncate it.
// Report keys embed their Metabase params (dates, filters) as a long encoded
// JSON string, so a fixed-length prefix collides across date ranges: the
// differing dates sit past the cutoff, so every range mapped to the same file
// and read back whichever window was written last (e.g. a 7-day request served
// the 30-day pre-warm/seed data). A sha256 is fixed-length and collision-free.
function cacheFileName(key) {
  return crypto.createHash('sha256').update(key).digest('hex') + '.json';
}

async function getDiskCached(key, orgSlug, reportType) {
  try {
    const fname = cacheFileName(key);
    const raw = await fs.promises.readFile(path.join(CACHE_DIR, fname), 'utf8');
    const entry = JSON.parse(raw);
    if (!entry || !entry.data || !entry.ts) return null;
    const ttl = ttlForKey(entry.key || key, entry.rt, entry.hist);
    if (Date.now() - entry.ts > ttl) return null; // too stale for a normal hit
    cacheStats.hits++;
    if (isWarmTarget(orgSlug, reportType)) {
      dataCache.set(key, { data: entry.data, ts: entry.ts, rt: entry.rt || '', hist: !!entry.hist, lastRead: Date.now() });
      enforceMemoryCap();
    }
    return { data: entry.data, ts: entry.ts };
  } catch { return null; }
}

// Persist / restore learned popularity so a hot report stays hot across
// deploys (each PR preview / restart otherwise starts cold).
function accessStateFile() { return path.join(DATA_DIR, "cache-access.json"); }
function saveAccessStats() {
  if (!_accessDirty) return;
  _accessDirty = false;
  try {
    const now = Date.now(), obj = {};
    for (const [bk, arr] of accessLog) {
      const recent = arr.filter(ts => now - ts < HOT_WINDOW_MS);
      if (recent.length) obj[bk] = recent;
    }
    fs.writeFile(accessStateFile(), JSON.stringify(obj), "utf8", () => {});
  } catch {}
}
function loadAccessStats() {
  try {
    const obj = readJSON(accessStateFile(), {});
    const now = Date.now();
    for (const bk of Object.keys(obj)) {
      const recent = (obj[bk] || []).filter(ts => now - ts < HOT_WINDOW_MS);
      if (recent.length) accessLog.set(bk, recent);
    }
    console.log("[cache] Loaded access stats for " + accessLog.size + " report(s)");
  } catch {}
}
setInterval(saveAccessStats, 5 * 60 * 1000);

// ── Request performance log (ring buffer, last 500 requests) ──
const REQUEST_LOG = [];
const REQUEST_LOG_MAX = 500;
function logRequest(entry) {
  REQUEST_LOG.unshift(entry);
  if (REQUEST_LOG.length > REQUEST_LOG_MAX) REQUEST_LOG.length = REQUEST_LOG_MAX;
}

const cacheStats = { hits: 0, misses: 0, prewarms: 0, prewarmSkips: 0, prewarmAborts: 0, healthCacheHits: 0, healthProbes: 0 };

// ── Metabase / read-replica health tracker ───────────────────────────
// Every Metabase fetch (live proxy + pre-warm) records its duration and
// whether it timed out. The pre-warm consults this before each query and
// paces itself — or backs off entirely — when the replica is struggling,
// instead of piling scheduled warm queries onto an already-slow database.
const MB_HEALTH_WINDOW_MS = 10 * 60 * 1000;
const mbHealthSamples = []; // { ts, ms, timeout }
function recordMbSample(ms, timedOut) {
  mbHealthSamples.push({ ts: Date.now(), ms, timeout: !!timedOut });
  if (mbHealthSamples.length > 300) mbHealthSamples.splice(0, 150);
}
function mbHealth() {
  const cutoff = Date.now() - MB_HEALTH_WINDOW_MS;
  const recent = mbHealthSamples.filter(s => s.ts >= cutoff);
  const timeouts = recent.filter(s => s.timeout).length;
  const avgMs = recent.length ? Math.round(recent.reduce((a, s) => a + s.ms, 0) / recent.length) : 0;
  return { samples: recent.length, timeouts, avgMs };
}
// Pace for the next pre-warm query: healthy → short gap, degraded → long
// gap, unhealthy → abort the rest of the cycle (user requests keep their
// stale-cache fallback; the next cycle retries when the replica recovers).
function prewarmPace() {
  const h = mbHealth();
  if (h.timeouts >= 2 || h.avgMs > 30000) return { abort: true, delayMs: 0, ...h };
  if (h.timeouts === 1 || h.avgMs > 15000) return { abort: false, delayMs: 12000, ...h };
  return { abort: false, delayMs: 3000, ...h };
}
const sleepMs = (ms) => new Promise(r => setTimeout(r, ms));

// Long-lived cache for users report (refreshed daily by cron)
const USERS_CACHE_TTL = 24 * 60 * 60 * 1000; // 24 hours
const usersCache = new Map(); // key: orgSlug → { data: result, ts: Date.now() }

function getCachedUsers(orgSlug) {
  const entry = usersCache.get(orgSlug);
  if (!entry) return null;
  if (Date.now() - entry.ts > USERS_CACHE_TTL) { usersCache.delete(orgSlug); return null; }
  return entry;
}

function setCacheUsers(orgSlug, data) {
  const entry = { data, ts: Date.now() };
  usersCache.set(orgSlug, entry);
  try {
    fs.writeFile(path.join(CACHE_DIR, 'users_' + orgSlug + '.json'), JSON.stringify({ key: 'users:' + orgSlug, data: entry.data, ts: entry.ts, rt: 'users' }), 'utf8', () => {});
  } catch {}
}

function getCachedEntry(key, orgSlug, reportType) {
  let entry = dataCache.get(key);
  // Fall back to base prewarm key ONLY if this request has no custom params.
  // If the key contains query params (date filters, etc.), don't fall back —
  // the pre-warm data has different dates and would silently serve wrong results.
  const baseKey = `${orgSlug}:${reportType}:`;
  if (!entry && orgSlug && reportType && key === baseKey) {
    entry = dataCache.get(baseKey);
  }
  if (!entry) { cacheStats.misses++; return null; }
  const ttl = reportTtlMs(orgSlug || String(key).split(":")[0], entry.rt, entry.hist);
  if (Date.now() - entry.ts > ttl) { dataCache.delete(key); cacheStats.misses++; return null; }
  cacheStats.hits++;
  entry.lastRead = Date.now(); // for LRU recency
  return entry;
}

function getCached(key, orgSlug, reportType) {
  const entry = getCachedEntry(key, orgSlug, reportType);
  return entry ? entry.data : null;
}

function setCache(key, data, reportType, hist) {
  const rt = reportType || '';
  const entry = { data, ts: Date.now(), rt, hist: !!hist, lastRead: Date.now() };
  // Always persist to the disk cache (the durable L2 — disk is ~$0.60/mo).
  let serialized = null;
  try {
    serialized = JSON.stringify({ key, data: entry.data, ts: entry.ts, rt: entry.rt, hist: entry.hist });
    const fname = cacheFileName(key);
    fs.writeFile(path.join(CACHE_DIR, fname), serialized, 'utf8', () => {});
  } catch {}
  // Memory policy: hold resident unless it's a big payload for a report that
  // isn't a warm target (those serve from disk instead). Then LRU-cap the set.
  const heavy = serialized ? serialized.length > HEAVY_ENTRY_BYTES : false;
  const keepResident = !CACHE_ADAPTIVE || !heavy || isWarmTarget(key.split(":")[0], rt);
  if (keepResident) {
    dataCache.set(key, entry);
    enforceMemoryCap();
  } else {
    dataCache.delete(key); // don't let a prior resident copy linger
  }
}

// Return cached data even if TTL-expired (for fallback when Metabase is down).
// Tries exact key first, then the base (prewarm) key for this org/report.
function getStaleCached(orgSlug, reportType, exactKey) {
  // Try exact key
  let entry = dataCache.get(exactKey);
  if (entry?.data) return { data: entry.data, ts: entry.ts };
  // Try base prewarm key (no params)
  const baseKey = `${orgSlug}:${reportType}:`;
  entry = dataCache.get(baseKey);
  if (entry?.data) return { data: entry.data, ts: entry.ts };
  // Try users cache for users report
  if (reportType === "users") {
    const uc = usersCache.get(orgSlug);
    if (uc?.data) return { data: uc.data, ts: uc.ts };
  }
  return null;
}

// ── Hydrate cache from disk on startup ──
// NOTE: called from below the CACHE_DIR declaration, NOT at module load —
// as an IIFE here it threw "Cannot access 'CACHE_DIR' before initialization"
// into its own catch on every boot, so the disk cache never hydrated and
// every restart started cold (which is what made the post-deploy pre-warm
// hammer the read replica).
function hydrateCacheFromDisk() {
  try {
    const files = fs.readdirSync(CACHE_DIR).filter(f => f.endsWith('.json'));
    let loaded = 0, expired = 0, userLoaded = 0;
    for (const file of files) {
      try {
        const raw = fs.readFileSync(path.join(CACHE_DIR, file), 'utf8');
        const entry = JSON.parse(raw);
        if (!entry.key || !entry.data || !entry.ts) continue;
        const ttl = ttlForKey(entry.key, entry.rt, entry.hist);
        if (Date.now() - entry.ts > ttl * 12) { // generous grace — stale data beats 502
          fs.unlink(path.join(CACHE_DIR, file), () => {});
          expired++;
          continue;
        }
        if (entry.key.startsWith('users:')) {
          usersCache.set(entry.key.replace('users:', ''), { data: entry.data, ts: entry.ts });
          userLoaded++;
        } else {
          dataCache.set(entry.key, { data: entry.data, ts: entry.ts, rt: entry.rt || '', hist: !!entry.hist });
          loaded++;
        }
      } catch {}
    }
    console.log('[cache] Hydrated from disk: ' + loaded + ' report entries, ' + userLoaded + ' users entries, ' + expired + ' expired/removed');
  } catch (err) {
    console.log('[cache] No disk cache to hydrate: ' + err.message);
  }
}

// ── One-shot facilities cache invalidation on card-UUID change ──
// The facilities cache key is UUID-agnostic (slug:facilities:params), so when
// FACILITIES_SUMMARY_UUID is re-pointed at a different Metabase card the disk-
// hydrated entries still hold the OLD card's rows — and prewarm skips entries
// that are still fresh (< 4h TTL), so it would never replace them. That would
// serve stale/undercounted numbers for up to 4h after a cutover. Detect the
// change against a persisted marker and drop the stale facilities entries
// (memory + disk) once, so v2 repopulates through the serial, self-throttling
// prewarm (and lazy per-org live fetches) — no thundering herd on Metabase.
// Must run AFTER hydrateCacheFromDisk() and AFTER CACHE_DIR is defined.
function invalidateFacilitiesCacheOnUuidChange() {
  const marker = path.join(DATA_DIR, "facilities-card-uuid.json");
  let prev = null;
  try { prev = readJSON(marker, {}).uuid || null; } catch {}
  if (prev === FACILITIES_SUMMARY_UUID) return;
  let dropped = 0;
  for (const [key, entry] of dataCache) {
    if (entry.rt === "facilities") {
      dataCache.delete(key);
      try {
        const fname = cacheFileName(key);
        fs.unlink(path.join(CACHE_DIR, fname), () => {});
      } catch {}
      dropped++;
    }
  }
  try { writeJSON(marker, { uuid: FACILITIES_SUMMARY_UUID, changedAt: new Date().toISOString() }); } catch {}
  console.log(`[cache] Facilities card UUID changed (${prev ? prev.slice(0, 8) : "none"} → ${FACILITIES_SUMMARY_UUID.slice(0, 8)}) — dropped ${dropped} stale facilities entr${dropped === 1 ? "y" : "ies"}; v2 will repopulate via prewarm`);
}

// Prune expired entries every 60 minutes — keep 2x TTL grace for stale fallback
setInterval(() => {
  const now = Date.now();
  for (const [k, v] of dataCache) {
    const ttl = ttlForKey(k, v.rt, v.hist);
    if (now - v.ts > ttl * 2) dataCache.delete(k);
  }
}, 60 * 60 * 1000);

// ── Org Pulse: monthly metrics from Metabase with month-over-month deltas ──
const pulseCache = new Map();
const PULSE_CACHE_TTL = 24 * 60 * 60 * 1000; // 24 hours — refreshed daily by cron

function getCachedPulse(slug) {
  const entry = pulseCache.get(slug);
  if (!entry) return null;
  if (Date.now() - entry.ts > PULSE_CACHE_TTL) { pulseCache.delete(slug); return null; }
  return entry.data;
}

const pulseFmt = (n) => n >= 10000 ? `${(n/1000).toFixed(1)}k` : n >= 1000 ? `${(n/1000).toFixed(1)}k` : String(Math.round(n));
const pulseFmtMoney = (d) => '$' + Math.round(d).toLocaleString('en-US');

// Server-side sparkline SVG generator (mirrors client-side sparkSVG in org.html)
function pulseSparkSVG(trail) {
  if (!trail || trail.length < 2) return '';
  const w = 56, h = 18, pad = 2;
  let max = -Infinity, min = Infinity;
  for (const v of trail) { if (v > max) max = v; if (v < min) min = v; }
  const range = max - min || 1;
  const pts = trail.map((v, i) => {
    const x = (i / (trail.length - 1)) * w;
    const y = (h - pad) - ((v - min) / range) * (h - pad * 2);
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  });
  const last = trail[trail.length - 1], first = trail[0];
  const color = last > first * 1.03 ? '#4ade80' : last < first * 0.97 ? '#f87171' : '#a5b4fc';
  const lp = pts[pts.length - 1].split(',');
  return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" style="display:block;margin:4px auto 0;opacity:0.85"><polyline points="${pts.join(' ')}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${lp[0]}" cy="${lp[1]}" r="1.5" fill="${color}"/></svg>`;
}

async function refreshOrgPulse(slug, force) {
  // Return cached if still fresh (unless force-refreshing)
  if (!force) { const cached = getCachedPulse(slug); if (cached) return cached; }

  const org = ORGS[slug];
  if (!org) return null;

  const now = new Date();
  // Generate 6 trailing monthly date ranges (oldest first) for sparklines
  const trailMonths = [];
  for (let mi = 5; mi >= 0; mi--) {
    const s = new Date(now.getFullYear(), now.getMonth() - mi, 1);
    const e = new Date(now.getFullYear(), now.getMonth() - mi + 1, 0);
    trailMonths.push({ start: s.toISOString().slice(0,10), end: e.toISOString().slice(0,10), label: s.toLocaleString('en-US', { month: 'short' }) });
  }
  const curStart = trailMonths[5].start, curEnd = trailMonths[5].end;
  const prevStart = trailMonths[4].start, prevEnd = trailMonths[4].end;
  const monthLabel = now.toLocaleString('en-US', { month: 'long' });
  const daysElapsed = Math.max(now.getDate(), 1);
  const daysInPrevMonth = new Date(now.getFullYear(), now.getMonth(), 0).getDate();
  const daysInCurMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();

  async function fetchMB(reportType, startDate, endDate) {
    const useShared = reportType === "gl" ? (!org.gl?.mbUuid && !!SHARED_UUIDS.gl) : !!SHARED_UUIDS[reportType];
    const mbUuid = useShared ? SHARED_UUIDS[reportType] : (org[reportType]?.mbUuid || SHARED_UUIDS[reportType]);
    if (!mbUuid) return null;
    try {
      const orgId = useShared ? org.orgId : null;
      const params = buildMetabaseParams({ start_date: startDate, end_date: endDate }, reportType, orgId);
      const qs = params.length ? `?parameters=${encodeURIComponent(JSON.stringify(params))}` : '';
      const resp = await fetch(`${METABASE_URL}/api/public/card/${mbUuid}/query/json${qs}`);
      if (!resp.ok) return null;
      return await resp.json();
    } catch(e) { console.warn(`[pulse] fetch failed ${slug}/${reportType}: ${e.message}`); return null; }
  }

  // Build human-readable date range for the pulse strip header
  const curMonthShort = now.toLocaleString('en-US', { month: 'short' });
  const curYear = now.getFullYear();
  const pulseDateRange = curMonthShort + ' 1\u2013' + daysElapsed + ', ' + curYear;
  const pulse = { items: [], generated: new Date().toISOString(), month: monthLabel, dateRange: pulseDateRange, trailLabels: trailMonths.map(m => m.label), priorMonth: trailMonths[4].label };

  // ── Fetch all report types × 6 months in parallel for sparklines ──
  const [glAll, pgAll, facAll, prodAll] = await Promise.all([
    Promise.all(trailMonths.map(m => fetchMB('gl', m.start, m.end))),
    Promise.all(trailMonths.map(m => fetchMB('programs', m.start, m.end))),
    Promise.all(trailMonths.map(m => fetchMB('facility', m.start, m.end))),
    Promise.all(trailMonths.map(m => fetchMB('products', m.start, m.end))),
  ]);

  // ── GL: revenue + refunds ──
  const glCur = glAll[5], glPrev = glAll[4];
  function sumGL(rows) {
    if (!rows || !rows.length) return { pay: 0, ref: 0 };
    const sk = Object.keys(rows[0]);
    const payK = sk.find(k => /total.?pay/i.test(k)) || 'Total Payments';
    const refK = sk.find(k => /total.?ref/i.test(k)) || 'Total Refunds';
    let pay = 0, ref = 0;
    for (const r of rows) { pay += parseFloat(r[payK]||0); ref += Math.abs(parseFloat(r[refK]||0)); }
    return { pay, ref };
  }
  if (glCur) {
    const cur = sumGL(glCur), prev = sumGL(glPrev||[]);
    const net = cur.pay - cur.ref, prevNet = prev.pay - prev.ref;
    const dailyCur = net / daysElapsed, dailyPrev = prevNet / daysInPrevMonth;
    const pace = Math.round(dailyCur * daysInCurMonth);
    const pct = dailyPrev ? Math.round((dailyCur - dailyPrev) / Math.abs(dailyPrev) * 100) : null;
    const glTrail = glAll.map(r => { const s = sumGL(r||[]); return s.pay - s.ref; });
    const refTrail = glAll.map(r => sumGL(r||[]).ref);
    pulse.items.push({ key:'revenue', label:'Revenue', value: pulseFmtMoney(net), sub: `day ${daysElapsed} • pace ${pulseFmtMoney(pace)}`, icon:'💰',
      delta: pct !== null ? (pct >= 0 ? `+${pct}%` : `${pct}%`) : null, direction: pct > 0 ? 'up' : pct < 0 ? 'down' : null, trail: glTrail });
    pulse.items.push({ key:'refunds', label:'Refunds', value: pulseFmtMoney(cur.ref), sub: `${((cur.ref/(cur.pay||1))*100).toFixed(1)}% of gross`, icon:'↩️',
      delta: null, direction: null, trail: refTrail });
  }

  // ── Programs: enrollments ──
  const pgCur = pgAll[5], pgPrev = pgAll[4];
  function sumProg(rows) {
    if (!rows || !rows.length) return { enroll: 0, cancel: 0, progs: 0 };
    const sk = Object.keys(rows[0]);
    const eK = sk.find(k => /^enroll/i.test(k)) || 'Enrollments';
    const cK = sk.find(k => /^cancel/i.test(k)) || 'Cancellations';
    const pK = sk.find(k => /^program$/i.test(k)) || 'Program';
    let e = 0, c = 0; const ps = new Set();
    for (const r of rows) { e += parseInt(r[eK])||0; c += parseInt(r[cK])||0; if (r[pK]) ps.add(r[pK]); }
    return { enroll: e, cancel: c, progs: ps.size };
  }
  if (pgCur) {
    const cur = sumProg(pgCur), prev = sumProg(pgPrev||[]);
    const eDailyCur = cur.enroll / daysElapsed, eDailyPrev = prev.enroll / daysInPrevMonth;
    const ePace = Math.round(eDailyCur * daysInCurMonth);
    const pct = eDailyPrev ? Math.round((eDailyCur - eDailyPrev) / Math.abs(eDailyPrev) * 100) : null;
    const enrollTrail = pgAll.map(r => sumProg(r||[]).enroll);
    pulse.items.push({ key:'enrollments', label:'Enrollments', value: pulseFmt(cur.enroll), sub: `${cur.progs} programs • pace ${pulseFmt(ePace)}`, icon:'🎓',
      delta: pct !== null ? (pct >= 0 ? `+${pct}%` : `${pct}%`) : null, direction: pct > 0 ? 'up' : pct < 0 ? 'down' : null, trail: enrollTrail });
  }

  // ── Facility: bookings ──
  const facCur = facAll[5], facPrev = facAll[4];
  if (facCur) {
    const locs = new Set();
    for (const r of facCur) { const l = r['Location']||r['location']||r['location_name']; if(l) locs.add(l); }
    const cc = facCur.length, pc = facPrev ? facPrev.length : 0;
    const bDailyCur = cc / daysElapsed, bDailyPrev = pc / daysInPrevMonth;
    const bPace = Math.round(bDailyCur * daysInCurMonth);
    const bPct = bDailyPrev ? Math.round((bDailyCur - bDailyPrev) / Math.abs(bDailyPrev) * 100) : null;
    const bookTrail = facAll.map(r => (r||[]).length);
    pulse.items.push({ key:'bookings', label:'Bookings', value: pulseFmt(cc), sub: `${locs.size} locations • pace ${pulseFmt(bPace)}`, icon:'📅',
      delta: bPct !== null ? (bPct >= 0 ? `+${bPct}%` : `${bPct}%`) : null, direction: bPct > 0 ? 'up' : bPct < 0 ? 'down' : null, trail: bookTrail });
  }

  // ── Products: POS ──
  const prodCur = prodAll[5], prodPrev = prodAll[4];
  function sumProd(rows) {
    if (!rows || !rows.length) return 0;
    const sk = Object.keys(rows[0]);
    const gK = sk.find(k => /gross.?rev|net.?rev/i.test(k)) || 'Gross Revenue';
    let t = 0; for (const r of rows) { t += parseFloat(r[gK]||0); } return t;
  }
  if (prodCur) {
    const cur = sumProd(prodCur), prev = sumProd(prodPrev||[]);
    if (cur > 0) {
      const pDailyCur = cur / daysElapsed, pDailyPrev = prev / daysInPrevMonth;
      const pPace = Math.round(pDailyCur * daysInCurMonth);
      const pPct = pDailyPrev ? Math.round((pDailyCur - pDailyPrev) / Math.abs(pDailyPrev) * 100) : null;
      const prodTrail = prodAll.map(r => sumProd(r||[]));
      pulse.items.push({ key:'productRev', label:'Product Sales', value: pulseFmtMoney(cur), sub: `${prodCur.length} items • pace ${pulseFmtMoney(pPace)}`, icon:'🛒',
        delta: pPct !== null ? (pPct >= 0 ? `+${pPct}%` : `${pPct}%`) : null, direction: pPct > 0 ? 'up' : pPct < 0 ? 'down' : null, trail: prodTrail });
    }
  }

  // ── Households (snapshot, no date range) ──
  const ue = getCachedUsers(slug);
  if (ue && ue.data && ue.data.rows) {
    const hh = new Set();
    for (const r of ue.data.rows) { const h = r['Household ID']||r['household_id']; if (h) hh.add(h); }
    if (hh.size > 0) pulse.items.push({ key:'households', label:'Households', value: pulseFmt(hh.size), sub: `${pulseFmt(ue.data.rows.length)} people`, icon:'🏠', delta: null, direction: null });
  }

  // ── Generate AI narrative (Rec Daily Insights) ──
  if (anthropic && pulse.items.length >= 2) {
    try {
      const summary = pulse.items.map(it => {
        let line = `${it.label}: ${it.value}`;
        if (it.sub) line += ` (${it.sub})`;
        if (it.delta) line += ` — ${it.delta} vs last month`;
        if (it.trail && it.trail.length >= 2) {
          const trend = it.trail[it.trail.length-1] > it.trail[0] ? 'trending up' : it.trail[it.trail.length-1] < it.trail[0] ? 'trending down' : 'flat';
          line += ` [6-month: ${trend}]`;
        }
        return line;
      }).join('\n');
      const orgName = ORGS[slug]?.displayName || slug;
      const resp = await anthropic.messages.create({
        model: INSIGHTS_MODEL,
        max_tokens: 300,
        system: `You are a parks & recreation analytics advisor for "${orgName}". Today is day ${daysElapsed} of ${monthLabel} (${daysInCurMonth} days total), so all month-over-month deltas are already normalized to daily run rate — do NOT flag partial-month data as a concern.\n\nKey distinctions: Enrollments = program registrations (classes, camps, lessons). Bookings = facility reservations (pavilion rentals, field rentals). These are separate funnels.\n\nWrite exactly 3 concise bullet insights (each 1 sentence, max 20 words). Focus on: (1) the most notable pace trend, (2) an actionable observation, (3) something positive or a watch-item. Return ONLY a JSON array of 3 strings.`,
        messages: [{ role: 'user', content: `Month: ${monthLabel}\n${summary}` }],
      });
      const raw = (resp.content || []).filter(c => c.type === 'text').map(c => c.text).join('');
      const parsed = JSON.parse(raw.replace(/```json|```/g, '').trim());
      if (Array.isArray(parsed) && parsed.length > 0) {
        pulse.narrative = parsed.slice(0, 3);
        console.log(`[pulse] ${slug}: AI narrative generated (${parsed.length} insights)`);
      }
    } catch(e) {
      console.warn(`[pulse] ${slug}: AI narrative failed: ${e.message}`);
    }
  }

  console.log(`[pulse] ${slug}: ${pulse.items.length} items, ${monthLabel}`);
  pulseCache.set(slug, { data: pulse, ts: Date.now() });
  return pulse;
}

// ── Cache pre-warm on startup ─────────────────────────────────────────
async function prewarmCache(reason = 'interval') {
  if (!getFlags().cachingEnabled) { console.log('[cache] Pre-warm skipped — caching is OFF'); return; }
  // After a restart, don't re-warm the world if a cycle completed recently —
  // the disk-hydrated cache already covers it. The 15-min interval and the
  // 4:50am cron keep freshness; this only suppresses the boot-time stampede
  // (each deploy used to fire a full warm against the read replica).
  if (reason === 'startup') {
    try {
      const state = readJSON(PREWARM_STATE_FILE, {});
      const age = state.lastCompletedAt ? Date.now() - new Date(state.lastCompletedAt).getTime() : Infinity;
      if (age < PREWARM_STARTUP_SKIP_MS) {
        cacheStats.prewarmSkips++;
        console.log(`[cache] Startup pre-warm skipped — last full warm ${Math.round(age / 60000)}m ago, serving hydrated disk cache`);
        return;
      }
    } catch {}
  }
  console.log(`[cache] Pre-warming default reports… (${reason})`);
  let warmed = 0;

  // Adaptive pacing: consult replica health before each Metabase query, wait
  // between queries, and abort the remainder of the cycle if the replica is
  // degraded. Aborted cycles don't stamp completion, so the next cycle retries.
  let prewarmFetches = 0;
  let prewarmAborted = false;
  async function paceOk() {
    const pace = prewarmPace();
    if (pace.abort) {
      prewarmAborted = true;
      cacheStats.prewarmAborts++;
      console.warn(`[cache] Pre-warm aborted — replica degraded (${pace.timeouts} timeouts, avg ${pace.avgMs}ms over last 10m); will retry next cycle`);
      return false;
    }
    if (prewarmFetches > 0) await sleepMs(pace.delayMs);
    prewarmFetches++;
    return true;
  }
  async function timedWarmFetch(url, timeoutMs) {
    const t0 = Date.now();
    try {
      const resp = await fetch(url, { signal: AbortSignal.timeout(timeoutMs) });
      recordMbSample(Date.now() - t0, false);
      return resp;
    } catch (e) {
      recordMbSample(Date.now() - t0, e.name === "TimeoutError" || e.name === "AbortError");
      throw e;
    }
  }

  // Build "this month" parameterized cache key so explicit date requests also hit cache
  const now = new Date();
  const monthStart = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;
  const lastDay = new Date(now.getFullYear(), now.getMonth()+1, 0).getDate();
  const monthEnd   = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(lastDay).padStart(2,'0')}`;
  const monthParams = [
    { type: "date/single", target: ["variable", ["template-tag", "start_date"]], value: monthStart },
    { type: "date/single", target: ["variable", ["template-tag", "end_date"]],   value: monthEnd },
  ];
  const monthParamStr = `?parameters=${encodeURIComponent(JSON.stringify(monthParams))}`;

  // Prior calendar month — warmed for the report types whose pages show
  // prior-period delta pills, so the default "This Month" view gets its
  // comparison numbers from cache instead of a live Metabase query.
  const priorStart = `${new Date(now.getFullYear(), now.getMonth()-1, 1).getFullYear()}-${String(new Date(now.getFullYear(), now.getMonth()-1, 1).getMonth()+1).padStart(2,'0')}-01`;
  const priorLastDay = new Date(now.getFullYear(), now.getMonth(), 0);
  const priorEnd = `${priorLastDay.getFullYear()}-${String(priorLastDay.getMonth()+1).padStart(2,'0')}-${String(priorLastDay.getDate()).padStart(2,'0')}`;
  const priorMonthParams = [
    { type: "date/single", target: ["variable", ["template-tag", "start_date"]], value: priorStart },
    { type: "date/single", target: ["variable", ["template-tag", "end_date"]],   value: priorEnd },
  ];
  const DELTA_PREWARM_REPORTS = new Set(["programs", "gl", "selfservice"]);

  outer:
  for (const slug of Object.keys(ORGS)) {
    const org = ORGS[slug];
    if (!org.token) continue;
    for (const rt of REPORT_TYPES) {
      // Skip big extracts (e.g. users, ice-calendar) for orgs where nobody
      // opens them — cuts both resident memory and Metabase egress. They stay
      // on-demand (live → disk L2) and auto-promote once opened often enough.
      if (!isWarmTarget(slug, rt)) continue;
      const useShared = rt === "gl" ? (!org.gl?.mbUuid && !!SHARED_UUIDS.gl) : !!SHARED_UUIDS[rt];
      const mbUuid = useShared ? SHARED_UUIDS[rt] : (org[rt]?.mbUuid || SHARED_UUIDS[rt]);
      if (!mbUuid) continue;
      // ── Prior-month warm for delta pills (runs even when current month is warm) ──
      if (DELTA_PREWARM_REPORTS.has(rt) && !NO_DATE_REPORTS.has(rt)) {
        try {
          const pParams = [];
          if (useShared && org.orgId) pParams.push({ type: "string/=", target: ["variable", ["template-tag", "org_id"]], value: org.orgId });
          pParams.push(...priorMonthParams);
          const pStr = `?parameters=${encodeURIComponent(JSON.stringify(pParams))}`;
          const priorKey = `${slug}:${rt}:${pStr}`;
          if (!getCached(priorKey)) {
            if (!await paceOk()) break outer;
            const resp = await timedWarmFetch(`${METABASE_URL}/api/public/card/${mbUuid}/query/json${pStr}`, org.healthTimeoutMs || 120000);
            if (resp.ok) {
              const data = await resp.json();
              setCache(priorKey, {
                rows: data,
                meta: { org_slug: slug, org_id: org.orgId, logo_url: org.logoUrl, report_type: rt, generated_at: new Date().toISOString() },
              }, rt, true);
              console.log(`[cache] Warmed prior-month ${slug}/${rt} (${data.length} rows)`);
            }
          }
        } catch (e) {
          console.warn(`[cache] Prior-month warm failed for ${slug}/${rt}: ${e.name === "TimeoutError" || e.name === "AbortError" ? "timeout" : e.message}`);
        }
      }
      if (HEALTH_SKIP_REPORTS.has(rt)) continue;
      // Only pre-warm reports with no required params (default = current month)
      const cacheKey = `${slug}:${rt}:`;
      if (getCached(cacheKey)) continue; // already warm
      try {
        const timeoutMs = org.healthTimeoutMs || 120000;
        // Build params: org_id (shared) + this-month dates (avoid querying all-time data)
        const fetchParams = [];
        if (useShared && org.orgId) {
          fetchParams.push({ type: "string/=", target: ["variable", ["template-tag", "org_id"]], value: org.orgId });
        }
        if (!NO_DATE_REPORTS.has(rt)) fetchParams.push(...monthParams);
        const paramStr = fetchParams.length > 0 ? `?parameters=${encodeURIComponent(JSON.stringify(fetchParams))}` : '';
        const url = `${METABASE_URL}/api/public/card/${mbUuid}/query/json${paramStr}`;
        if (!await paceOk()) break outer;
        const resp = await timedWarmFetch(url, timeoutMs);
        if (resp.ok) {
          let data = await resp.json();
          // Strip PII for calendar
          if (rt === "calendar" && Array.isArray(data)) {
            const PII = new Set(["reservee","reservee name","customer","customer name","booked by","booker","contact","contact name","notes","note","address","first name","last name","name"]);
            const isPII = (k) => { const t = String(k).toLowerCase().trim(); return PII.has(t) || t.includes("email") || t.includes("phone"); };
            for (const row of data) {
              if (row && typeof row === "object" && !Array.isArray(row)) {
                for (const k of Object.keys(row)) { if (isPII(k)) delete row[k]; }
              }
            }
          }
          const result = {
            rows: data,
            meta: { org_slug: slug, org_id: org.orgId, logo_url: org.logoUrl, report_type: rt, generated_at: new Date().toISOString() },
          };
          setCache(cacheKey, result, rt);
          // Also store under the full paramStr key (with org_id + dates) so
          // normal requests get a cache hit, not just prewarm base-key lookups.
          // THROUGH feedCacheKey, because these keys have to match the ones the
          // data route builds — for a long time they did not, and every entry
          // written here was unreachable.
          if (paramStr) setCache(feedCacheKey(slug, rt, paramStr), result, rt);
          // Also store under the explicit "This Month" cache key so users who
          // click This Month (which sends start_date + end_date params) get a
          // cache hit instead of re-querying Metabase.
          const monthKeyWithOrg = useShared && org.orgId
            ? `?parameters=${encodeURIComponent(JSON.stringify([{ type: "string/=", target: ["variable", ["template-tag", "org_id"]], value: org.orgId }, ...monthParams]))}`
            : monthParamStr;
          setCache(feedCacheKey(slug, rt, monthKeyWithOrg), result, rt);

          // ── The window the PAGE will actually open on ──
          // Opt-in per org (roster `warmDefaultWindow`, default OFF) because it
          // is one more Metabase query per org per day — a load increase should
          // be switched on and measured, not slipped in. What it buys: the Class
          // Roster's first open is otherwise a cold query on a window nothing
          // has warmed. Built with the REAL buildMetabaseParams so the key is
          // the one the route computes, not an approximation of it.
          try {
            if (reportSettingsEnabled(rt) && reportSettings(slug, rt).warmDefaultWindow) {
              const days = reportSettings(slug, rt).defaultDays;
              if (Number.isFinite(days) && days > 0) {
                const t0 = new Date();
                const start = new Date(t0.getFullYear(), t0.getMonth(), t0.getDate());
                const end = new Date(start.getFullYear(), start.getMonth(), start.getDate() + days - 1);
                const iso = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
                const dp = buildMetabaseParams({ start_date: iso(start), end_date: iso(end) }, rt, org.orgId);
                const dpStr = dp.length ? `?parameters=${encodeURIComponent(JSON.stringify(dp))}` : "";
                const defKey = feedCacheKey(slug, rt, dpStr);
                if (!getCached(defKey) && await paceOk()) {
                  const r2 = await timedWarmFetch(`${METABASE_URL}/api/public/card/${mbUuid}/query/json${dpStr}`, timeoutMs);
                  if (r2.ok) {
                    const d2 = await r2.json();
                    setCache(defKey, { rows: d2, meta: { org_slug: slug, org_id: org.orgId, logo_url: org.logoUrl, report_type: rt, generated_at: new Date().toISOString() } }, rt);
                    console.log(`[cache] Warmed ${slug}/${rt} default window ${iso(start)}→${iso(end)} (${d2.length} rows)`);
                  }
                }
              }
            }
          } catch (e) {
            console.warn(`[cache] Default-window warm failed for ${slug}/${rt}: ${e.message}`);
          }
          warmed++;
          console.log(`[cache] Warmed ${slug}/${rt} (${data.length} rows)`);
        }
      } catch (e) {
        const label = e.name === "TimeoutError" || e.name === "AbortError" ? "timeout" : e.message;
        console.warn(`[cache] Pre-warm failed for ${slug}/${rt}: ${label}`);
      }
    }
    // ── Facilities hub summary — not in REPORT_TYPES, so the loop above never
    // warms it. Big orgs' summary card can take 60-100s cold (SF), which times
    // out browser-initiated fetches and renders the hub as "0 bookings"; warm
    // the default current-month view so the page hits cache instead.
    if (org.orgId) {
      const facParams = [
        { type: "string/=", target: ["variable", ["template-tag", "org_id"]], value: org.orgId },
        ...monthParams,
      ];
      const facStr = `?parameters=${encodeURIComponent(JSON.stringify(facParams))}`;
      const facKey = `${slug}:facilities:${facStr}`;
      if (!getCached(facKey, slug, "facilities")) {
        try {
          if (!await paceOk()) break outer;
          const resp = await timedWarmFetch(`${METABASE_URL}/api/public/card/${FACILITIES_SUMMARY_UUID}/query/json${facStr}`, org.healthTimeoutMs || 180000);
          if (resp.ok) {
            const data = await resp.json();
            const result = { rows: Array.isArray(data) ? data : [], meta: { org_slug: slug, org_id: org.orgId, report_type: "facilities", generated_at: new Date().toISOString() } };
            setCache(facKey, result, "facilities");
            warmed++;
            console.log(`[cache] Warmed ${slug}/facilities (${result.rows.length} rows)`);
          }
        } catch (e) {
          console.warn(`[cache] Pre-warm failed for ${slug}/facilities: ${e.name === "TimeoutError" || e.name === "AbortError" ? "timeout" : e.message}`);
        }
      }
    }
  }
  cacheStats.prewarms++;
  if (prewarmAborted) {
    console.log(`[cache] Pre-warm cycle aborted after ${warmed} report(s) cached (cycle #${cacheStats.prewarms})`);
    return;
  }
  try { writeJSON(PREWARM_STATE_FILE, { lastCompletedAt: new Date().toISOString() }); } catch {}
  console.log(`[cache] Pre-warm complete: ${warmed} reports cached (cycle #${cacheStats.prewarms})`);
}

// ── Dashboard authentication ─────────────────────────────────────────
// Set DASHBOARD_PASSWORD in Railway env vars.
// /hotdog and /api/hotdog are public (no auth required).
const DASHBOARD_PASSWORD = process.env.DASHBOARD_PASSWORD || '';
const RECOMMEND_ENABLED  = process.env.RECOMMEND_ENABLED === 'true'; // off until rec.us domain is verified in Resend; set RECOMMEND_ENABLED=true to re-enable

function dashboardAuth(req, res, next) {
  // Only protect the root dashboard; all org routes and /hotdog are public
  if (req.path !== '/') return next();

  // No password configured → open access (dev/staging fallback)
  if (!DASHBOARD_PASSWORD) return next();

  const auth = req.headers['authorization'] || '';
  if (auth.startsWith('Basic ')) {
    const decoded  = Buffer.from(auth.slice(6), 'base64').toString('utf-8');
    const password = decoded.includes(':') ? decoded.split(':').slice(1).join(':') : decoded;
    if (password === DASHBOARD_PASSWORD) {
      // Signing in here is what makes the report-settings gear appear on the org
      // reports you then navigate to. Basic auth is scoped to "/" by the browser,
      // so without this a super-admin had to paste &admin=<key> onto every report
      // URL by hand — which is also the worse credential: a URL leaks through
      // history, referrers and copy-paste, a cookie does not.
      //
      // The VALUE IS THE DERIVED KEY, NEVER THE PASSWORD. If this cookie leaks it
      // opens the settings panel and nothing else, and rotating the password
      // rotates it. HttpOnly because no page ever reads it (the server injects
      // settingsAdmin into ORG_CONFIG); SameSite=Lax so it rides a normal click
      // through from the dashboard but is NOT sent on a cross-site PUT.
      setReportSettingsCookie(req, res);
      return next();
    }
  }

  res.set('WWW-Authenticate', 'Basic realm="Rec Reports", charset="UTF-8"');
  return res.status(401).send('Password required');
}

// One cookie, read by hand — the app has no cookie middleware and one name does
// not justify adding one.
const RS_ADMIN_COOKIE = 'rs_admin';
const RS_ADMIN_COOKIE_MAX_AGE = 12 * 60 * 60; // seconds

function readCookie(req, name) {
  const raw = req.headers && req.headers.cookie;
  if (!raw) return '';
  for (const part of String(raw).split(';')) {
    const i = part.indexOf('=');
    if (i < 0) continue;
    if (part.slice(0, i).trim() === name) {
      try { return decodeURIComponent(part.slice(i + 1).trim()); }
      catch (_) { return part.slice(i + 1).trim(); }
    }
  }
  return '';
}

function setReportSettingsCookie(req, res) {
  const key = reportSettingsAdminKey();
  if (!key) return; // fails closed: no password, no key, no cookie
  // Secure only over https, or the cookie is dropped on http://localhost in dev
  // and the gear silently never appears there.
  const https = req.secure || String(req.headers['x-forwarded-proto'] || '').split(',')[0].trim() === 'https';
  res.append('Set-Cookie',
    RS_ADMIN_COOKIE + '=' + key +
    '; Path=/; Max-Age=' + RS_ADMIN_COOKIE_MAX_AGE +
    '; HttpOnly; SameSite=Lax' + (https ? '; Secure' : ''));
}

