  "section-detail": "bbb347c8-9e2d-446d-b014-a86a9d14115a",
  checkins: "574324e0-b5a1-46c5-8770-8c466631fdcf",
  "program-checkins": "cb6fd909-72d3-446b-930b-c0382da02d62",
