const NON_ADDABLE_REPORTS = new Set(["program-demographics", "retention", "annual-report", "section-detail", "qoq", "checkins", "program-checkins", "selfservice"]);
// Reports that require extra params (e.g. section_id) and cannot be health-checked with org_id alone
// How many consecutive failed probes before a report is called down. One is
// load; two in a row is a report. See the flap note in checkOne().
const HEALTH_ALERT_AFTER = Number(process.env.HEALTH_ALERT_AFTER || 2);
const HEALTH_SKIP_REPORTS = new Set(["section-detail", "annual-report", "qoq", "qbr-stats", "checkins", "program-checkins", "selfservice"]);
const RENTAL_CALENDAR_ORGS = new Set(["watertown", "norman", "niagarafalls"]);
// Director's Report (quarterly executive summary) — org-wide since 2026-08-04
// (piloted on Watertown earlier the same day). With ALL_ORGS true every org
// gets the dashboard hero + auto-generated quarterly snapshots; individual
// orgs can still be switched off via the normal hidden-report toggle. Flip
// ALL_ORGS to false to fall back to the explicit pilot set below.
// Instructor Lessons report — pilot: SF only (their marketplace runs 60+
// instructors). Add slugs to expand; the page works for any org whose
// instructor-payout feed has lesson registrations.
const LESSONS_REPORT_ORGS = new Set(["san-francisco-rec-park"]);
const lessonsReportEnabled = (slug) => LESSONS_REPORT_ORGS.has(slug);

const DIRECTORS_REPORT_ALL_ORGS = true;
const DIRECTORS_REPORT_ORGS = new Set(["watertown"]);
const DIRECTORS_REPORT_EXCLUDED = new Set(["apex"]); // per Dan 2026-08-04 — everyone except Apex
const directorsReportEnabled = (slug) =>
  !DIRECTORS_REPORT_EXCLUDED.has(slug) && (DIRECTORS_REPORT_ALL_ORGS || DIRECTORS_REPORT_ORGS.has(slug));

// ── Org banner for report heroes ────────────────────────────────────
// Explicit ORGS.bannerUrl override → the org's own rec.us headerImage → the
// same default hero asset rec.us itself falls back to. rec.us stores the
// upload with its ORIGINAL extension (headerImage.jpeg is as common as .png —
// every current org has one), so probe the common extensions. Existence is
// HEAD-checked once per org per day so a newly uploaded banner shows up
// without a deploy.
const REC_DEFAULT_BANNER = "https://prod-rec-tech-img-bucket-8656aa2.s3.us-west-1.amazonaws.com/assets/images/rec-tennis.jpg";
const BANNER_EXTS = ["png", "jpeg", "jpg", "webp"];
const _bannerCache = new Map(); // orgId → { url, ts }
const BANNER_CACHE_TTL = 24 * 60 * 60 * 1000;
async function resolveBannerUrl(org) {
  if (org.bannerUrl) return org.bannerUrl;
  if (!org.orgId) return REC_DEFAULT_BANNER;
  const hit = _bannerCache.get(org.orgId);
  if (hit && Date.now() - hit.ts < BANNER_CACHE_TTL) return hit.url;
  let url = REC_DEFAULT_BANNER;
  for (const ext of BANNER_EXTS) {
    const candidate = "https://prod-rec-tech-img-bucket-8656aa2.s3.us-west-1.amazonaws.com/organization-" + org.orgId + "/headerImage." + ext;
    try {
      const r = await fetch(candidate, { method: "HEAD", signal: AbortSignal.timeout(4000) });
      if (r.ok) { url = candidate; break; }
    } catch (_) { /* try next extension */ }
  }
  _bannerCache.set(org.orgId, { url, ts: Date.now() });
  return url;
}
// Reports HIDDEN by default for every org (opt-in to show), for WIP reports not
// yet launched. For these, presence in an org's visibility list means SHOWN —
// the inverse of the normal opt-out hidden-list semantics. Use reportHiddenForOrg().
// (Facilities graduated out of here — it's now visible by default, replacing the
//  retired standalone Court Utilization card.)
const DEFAULT_HIDDEN_REPORTS = new Set([]);
// Reports RETIRED as standalone cards: kept as valid report types + endpoints
// (so the Facilities hub's native Court Utilization tab, chat, and /api/data all
// keep working) but no longer rendered as a clickable card on org/admin grids.
// Globally not-surfaced reports. Routes/code stay intact; they just aren't shown
// anywhere. chat is deprecated in favor of Rec's "Seb" AI skill.
// campmap stays retired as a REPORT — it is not one. It is a public artifact,
// and the way in is a direct link from the Facilities hub's Camping tab, which
// is where admins already manage the pins (Dan, 2026-08-22). The page itself
// never stopped working: /:org/campmap has been serving 200s to ~24 visitors a
// month through direct links the whole time it has been listed here, because
// this Set only controls whether it is SURFACED, not whether it works.
//
// report-wizard is UN-retired (Dan, 2026-08-20). It was shelved alongside chat
// as "deprecated in favor of Seb", but unlike chat it does something Seb does
// not: it builds a saved, shareable report config against the org's own report
// schemas. Nothing was deleted when it was retired — the page, the generate
// route and the feedback route all stayed — so bringing it back is removing it
// from this Set, not a rebuild.
const RETIRED_REPORTS = new Set(["court-utilization", "chat", "campmap"]);

// ── Dynamic orgs (added via dashboard UI) ────────────────────────────
// Loaded at startup and merged into ORGS; also updated at runtime.
// ── File storage ─────────────────────────────────────────────────────
const DATA_DIR = process.env.DATA_DIR || path.join(__dirname, "data");
fs.mkdirSync(DATA_DIR, { recursive: true });
const CACHE_DIR = path.join(DATA_DIR, "cache");
fs.mkdirSync(CACHE_DIR, { recursive: true });
hydrateCacheFromDisk();
loadAccessStats();
invalidateFacilitiesCacheOnUuidChange();
// Pre-warm bookkeeping — records when a full warm cycle last completed so a
// restart shortly after one can serve the hydrated disk cache instead of
// re-querying Metabase for every org.
const PREWARM_STATE_FILE = path.join(DATA_DIR, "prewarm-state.json");
const PREWARM_STARTUP_SKIP_MS = 6 * 60 * 60 * 1000;
// Persistence check: confirm campsite-map positions + other state land on a durable
// disk. In Railway, attach a Volume and set DATA_DIR to its mount path (e.g. /data).
console.log("[data] DATA_DIR=" + DATA_DIR +
  (process.env.DATA_DIR ? " (from env — persistent if this is a mounted Railway volume)"
                        : " (default ./data — EPHEMERAL; attach a Railway volume + set DATA_DIR to persist)"));

const ORGS_FILE          = path.join(DATA_DIR, "orgs.json");
const HOTDOG_CLAIMS_FILE = path.join(DATA_DIR, "hotdog_claims.json");

// ── Campsite map: admin-placed site coordinates ──────────────────────
// { slug: { siteId: { lat, lng } } } — set via the campmap editor (token-gated).
const CAMPMAP_POS_FILE = path.join(DATA_DIR, "campmap_positions.json");
let campmapPositions = {};
try { campmapPositions = JSON.parse(fs.readFileSync(CAMPMAP_POS_FILE, "utf8")); } catch { campmapPositions = {}; }
function saveCampmapPositions() {
  try { fs.writeFileSync(CAMPMAP_POS_FILE, JSON.stringify(campmapPositions, null, 2)); }
  catch (e) { console.error("[campmap] save positions failed:", e.message); }
}
// Admin-created custom map markers (Boat Ramp, etc.): { slug: [ {id,label,text,color,lat,lng} ] }
// Edited via the Camping tab's map editor (POST /:org/facilities/api/campsite-markers).
const CAMPMAP_MARKERS_FILE = path.join(DATA_DIR, "campmap_markers.json");
let campmapMarkers = {};
try { campmapMarkers = JSON.parse(fs.readFileSync(CAMPMAP_MARKERS_FILE, "utf8")); } catch { campmapMarkers = {}; }
