// ── Dead-link watch ──────────────────────────────────────────────────────────
// A link that used to work and now 404s is invisible to every other check here:
// the health check probes orgs that EXIST, so an org that was renamed or removed
// is simply not looked at, while the URL keeps circulating in emails and
// bookmarks. Found the hard way — /town-of-shrewsbury/users?token=… had been
// dead since the duplicate slug was removed on 2026-07-20 (the org is served as
// `shrewsbury`), and nothing noticed until someone clicked it.
//
// THE TOKEN IS THE WHOLE DISCRIMINATOR. This server is scanned constantly, so
// alerting on every 404 would be bot noise and would get muted within a day —
// which is worse than no alert. A scanner does not know our token shape; a
// stale internal link carries the token it was minted with. So: a 404 is only
// interesting if the request brought a token.
//
// Hooked on the RESPONSE rather than at each 404 site. There are ~30 places that
// send a 404 (resolveOrg, plus every page route's own guard), and a middleware
// that reads the finished status catches all of them — including any added later,
// which is the point of a guard.
const DEADLINK_IGNORE = /\.(php|env|git|aspx?|jsp|cgi|ini|ya?ml|sql|bak|zip|tar|gz)$|^\/(wp-|\.well-known|cgi-bin|vendor|admin\/config)/i;

// A 404 that is a REFUSAL, not a missing page. noteDeadLink() below watches for
// stale internal links and keys on "a 404 that arrived with a valid-looking
// token" — which is EXACTLY the shape of a deliberate refusal, so without this
// marker every refused request posts a DEAD LINK alert naming the very path the
// 404 exists to keep quiet. Found by Dan clicking into settings and getting the
// alert in Slack.
function refuse404(res, body) {
  res.locals.deliberate404 = true;
  return res.status(404).json(body || { error: "Not found" });
}

function noteDeadLink(req, res) {
  try {
    if (res.statusCode !== 404) return;
    // A refusal is not a dead link: the path is real, the caller was told no.
    if (res.locals && res.locals.deliberate404) return;
    // No token, no signal — see above.
    const tok = req.query && req.query.token;
    if (!tok || typeof tok !== "string" || tok.length < 8) return;
    const pathOnly = String(req.path || "").slice(0, 120);
    if (DEADLINK_IGNORE.test(pathOnly)) return;
    const seg = pathOnly.split("/").filter(Boolean);
    const slug = seg[0] || "";
    const report = seg[1] || "";
    // Which half was wrong decides what the fix is: a renamed org, or a report
    // that no longer exists for an org that does.
    const reason = ORGS[slug] ? "unknown-report" : "unknown-org";
    // A near-miss on the slug is the most useful thing we can say — it is almost
    // always a rename, and naming the survivor turns the alert into the fix.
    let suggest;
    if (reason === "unknown-org" && slug) {
      const base = slug.replace(/^(town|city|village|county)-of-/, "").replace(/-(ca|ma|nv|mo|tn|nc|ga|ny)$/, "");
      suggest = Object.keys(ORGS).find(k => k === base || k.indexOf(base) >= 0 || base.indexOf(k) >= 0);
    }
    logEvent(slug || "-", report || "-", "deadlink", req, {
      path: pathOnly, reason, suggest: suggest || undefined,
      // Deliberately NOT the token itself.
      hadToken: true,
    });
  } catch (e) {
    console.warn("[deadlink] watch failed:", e.message);
  }
}
app.use((req, res, next) => { res.on("finish", () => noteDeadLink(req, res)); next(); });
// ── Inter font injection ─ auto-injects into every HTML res.send ─────────────
const FONT_INJECT = '<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet"><style>body,input,select,button,textarea{font-family:\'Inter\',system-ui,-apple-system,sans-serif !important}</style>';

// rec.us logo (same asset as the favicon) as a data URI — inlined so the deploy
// overlay's logo renders even while the server is briefly unreachable.
const REC_LOGO = 'data:image/png;base64,';

// Deploy-watch: injected into every page. Pings /healthz; on a blip (deploy or
// crash-restart) it shows a branded "Deploying" overlay and auto-reloads when
// the server is back — so an in-progress deploy never shows a broken/reloading
// page to someone with a tab open. Idle poll is light (15s); tightens to 2s
// once a blip is detected, and also checks on tab focus / network reconnect.
// Recovery reloads as soon as the origin is reachable AGAIN (any HTTP response,
// not just a clean 200), because after a deploy swap the browser's reused
// keep-alive connection is often dead — background fetch()es keep failing while
// a full-page navigation would get a fresh connection. A blind-reload fallback
// (after ~6s down) forces that fresh navigation, and an always-present
// "Reload now" button guarantees the user is never stuck.
const DEPLOY_WATCH_INJECT = `<script>
(function(){
  if(window.__recDeployWatch)return; window.__recDeployWatch=1;
  var down=false, fast=null, ov=null, downAt=0;
  function reload(){ try{ location.reload(); }catch(e){ location.href = location.pathname + location.search; } }
  function overlay(){
    if(ov)return;
    ov=document.createElement('div');
    ov.style.cssText='position:fixed;inset:0;z-index:2147483647;display:flex;align-items:center;justify-content:center;background:rgba(15,17,23,.94);font-family:Inter,system-ui,-apple-system,sans-serif';
    ov.innerHTML='<div style="text-align:center;color:#e0e0e0;max-width:440px;padding:40px">'
      +'<img src="${REC_LOGO}" alt="rec.us" style="height:46px;width:46px;display:block;margin:0 auto 7px;border-radius:11px;box-shadow:0 3px 14px rgba(13,148,136,.45)">'
      +'<div style="font-size:12px;font-weight:700;letter-spacing:2.5px;text-transform:uppercase;color:#5eead4;margin-bottom:22px">rec.us</div>'
      +'<div style="font-size:38px;margin-bottom:12px">🚀</div>'
      +'<div style="font-size:20px;font-weight:700;color:#fff;margin-bottom:8px">Deploying an update</div>'
      +'<div style="font-size:13px;color:#9aa8b8;line-height:1.6;margin-bottom:20px">The platform is updating with the latest changes.<br>Reconnecting automatically — no need to refresh.</div>'
      +'<div style="width:34px;height:34px;border:3px solid #1e2a2a;border-top-color:#14b8a6;border-radius:50%;margin:0 auto 20px;animation:recspin .8s linear infinite"></div>'
      +'<button id="recReloadNow" style="background:#0d9488;color:#fff;border:none;border-radius:8px;padding:9px 22px;font-family:inherit;font-size:13px;font-weight:600;cursor:pointer;box-shadow:0 2px 12px rgba(13,148,136,.45)">Reload now</button>'
      +'<style>@keyframes recspin{to{transform:rotate(360deg)}}</style></div>';
    if(document.body){ document.body.appendChild(ov); var b=ov.querySelector('#recReloadNow'); if(b) b.addEventListener('click', reload); }
  }
  // Any HTTP response (even a 503 during warmup) means the origin is reachable;
  // a network error (rejection) means it is down.
  function probe(){ return fetch('/healthz?_='+Date.now(),{cache:'no-store'}).then(function(){return true;}).catch(function(){return false;}); }
  function check(){ probe().then(function(up){
    if(up){ if(down) reload(); return; }
    if(!down){ down=true; downAt=Date.now(); overlay(); if(!fast) fast=setInterval(check,2000); }
    else if(Date.now()-downAt > 6000){ reload(); } // fetch stuck on a dead keep-alive conn — force a fresh navigation
  }); }
  setInterval(check, 15000);
  window.addEventListener('focus', check);
  window.addEventListener('online', check);
})();
</script>`;

app.use((req, res, next) => {
  const _send = res.send;
  res.send = function(body) {
    if (typeof body === "string" && body.includes("</head>")) {
      body = body.replace("</head>", FONT_INJECT + DEPLOY_WATCH_INJECT + "\n</head>");
    }
    return _send.call(this, body);
  };
  next();
});


// ── Maintenance mode ─────────────────────────────────────────────────
// Toggled from the admin panel (Feature Flags → Maintenance Mode) or forced
// with MAINTENANCE_MODE=1. All org-facing traffic gets a branded 503 splash;
// the root admin dashboard (/) and /api/admin/* stay reachable so it can be
// turned back off. The splash polls /api/maintenance-status and reloads
// itself the moment maintenance ends.
const MAINTENANCE_PAGE = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Down for Maintenance</title>
<link rel="icon" type="image/png" href="/favicon.png">
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { min-height: 100vh; display: flex; align-items: center; justify-content: center;
    background: #0f1117; color: #e0e0e0; font-family: -apple-system, BlinkMacSystemFont, sans-serif; }
  .card { text-align: center; max-width: 480px; padding: 48px 36px; }
  .logo { height: 46px; width: 46px; border-radius: 11px; box-shadow: 0 3px 14px rgba(13,148,136,.45);
    display: block; margin: 0 auto 7px; }
  .brand { font-size: 12px; font-weight: 700; letter-spacing: 2.5px; text-transform: uppercase;
    color: #5eead4; margin-bottom: 26px; }
  .emoji { font-size: 40px; margin-bottom: 14px; }
  h1 { font-size: 24px; font-weight: 700; margin-bottom: 10px; color: #fff; }
  p { font-size: 14px; color: #9aa8b8; line-height: 1.6; margin-bottom: 26px; }
  .pulse { width: 10px; height: 10px; background: #f59e0b; border-radius: 50%; margin: 0 auto;
    animation: pulse 1.6s ease-in-out infinite; }
  @keyframes pulse { 0%,100% { opacity: .35; transform: scale(.85); } 50% { opacity: 1; transform: scale(1.15); } }
  .hint { margin-top: 22px; font-size: 11px; color: #555; }
</style>
</head>
<body>
<div class="card">
  <img class="logo" src="${REC_LOGO}" alt="rec.us">
  <div class="brand">rec.us</div>
  <div class="emoji">\u{1F6E0}️</div>
  <h1>Down for Maintenance</h1>
  <p>We'll be back up soon and even better!<br>This page will reconnect automatically — no need to refresh.</p>
  <div class="pulse"></div>
  <div class="hint">rec.us Analytics Platform</div>
</div>
<script>
  // Poll maintenance status and reload the moment the platform is back.
  (function(){
    function tick(){
      fetch('/api/maintenance-status',{cache:'no-store'})
        .then(function(r){ return r.json(); })
        .then(function(j){ if(!j.maintenance) location.reload(); })
        .catch(function(){});
    }
    setInterval(tick, 10000);
    window.addEventListener('focus', tick);
    window.addEventListener('online', tick);
  })();
</script>
</body>
</html>`;

// Public (unauthenticated) — the splash page polls this to know when to reload.
app.get("/api/maintenance-status", (req, res) => {
  res.set("Cache-Control", "no-store");
  res.json({ maintenance: isMaintenanceMode() });
});

app.use((req, res, next) => {
  if (!isMaintenanceMode()) return next();
  // Keep the admin dashboard + admin API reachable so maintenance can be
  // toggled back off (/ is already behind dashboardAuth's Basic auth).
  if (req.path === "/" || req.path.startsWith("/api/admin/")) return next();
  if (req.path === "/healthz" || req.path === "/api/maintenance-status") return next();
  if (req.path.match(/\.(css|js|ico|png|jpg|svg|woff2?)$/)) return next();
  res.set("Retry-After", "300");
  // Open tabs still fire background API calls — give those JSON, not HTML.
  if (req.path.includes("/api/")) {
    return res.status(503).json({ error: "Down for maintenance — we'll be back up soon and even better!", maintenance: true });
  }
  res.status(503).send(MAINTENANCE_PAGE);
});

