// ── Fast Track pins (shared per-org, persisted to the data volume) ──
// Pins are team state: any staff member with the org token sees the same
// pinned sections at the top of the Fast Track Overview.
const FT_PINS_FILE = path.join(DATA_DIR, "ft-pins.json");
function ftPinsAuth(req, res) {
  const org = ORGS[req.params.org];
  if (!org) { res.status(404).json({ error: "Unknown org" }); return null; }
  const supplied = req.query.token || req.headers["x-token"] || (req.body && req.body.token) || "";
  if (org.token && supplied !== org.token) { res.status(403).json({ error: "Invalid token" }); return null; }
  return org;
}
app.get("/:org/fasttrack/api/pins", (req, res) => {
  if (!ftPinsAuth(req, res)) return;
  const all = readJSON(FT_PINS_FILE, {});
  res.json({ pins: Array.isArray(all[req.params.org]) ? all[req.params.org] : [] });
});
app.post("/:org/fasttrack/api/pins", (req, res) => {
  if (!ftPinsAuth(req, res)) return;
  const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
  const raw = req.body?.pins;
  if (!Array.isArray(raw)) return res.status(400).json({ error: "pins must be an array of section ids (max 10)" });
  const pins = raw.filter(x => typeof x === "string" && UUID_RE.test(x)).slice(0, 10);
  // A non-empty request where nothing validates is a malformed client, not an
  // intentional clear — reject rather than silently wiping the team's pins.
  if (raw.length > 0 && pins.length === 0) return res.status(400).json({ error: "no valid section ids in pins" });
  const all = readJSON(FT_PINS_FILE, {});
  all[req.params.org] = pins;
  writeJSON(FT_PINS_FILE, all);
  res.json({ ok: true, pins });
});

// ── Saved views (per-org, per-report; team state on the data volume) ──
// A saved view is a NAME + a validated filter query string + a date intent —
// never a snapshot of rows. Applying one is a query-string swap on the report
// page, so the PDF / print / Excel / email paths inherit it without needing to
// know saved views exist.
//
// Shared per org, like the Fast Track pins above: auth is one token per org, so
// there is no per-user list to build yet. `owner` is reserved for that day
// (always null today) so a per-user model can land without a shape migration.
//
// Deliberately NOT wired into SLACK_NOTIFY: a view picker is a high-frequency
// internal convenience, not feed-worthy. The logEvent calls below still write
// events.jsonl so /metrics can answer whether anyone actually uses this — which
// is the gate on rolling saved views out to other reports.
const SAVED_VIEWS_FILE = path.join(DATA_DIR, "saved-views.json");
// Registry: report → the query params one of its saved views may carry. Only
// `gl` is registered; every other report 404s until someone asks for it. Dates
// are NOT in here — they travel as a date intent (see normalizeViewInput), so
// there is exactly one source of truth for a view's range.
const SAVED_VIEW_PARAMS = {
  gl: ["desks", "methods", "glq", "tyler"],
  // The Class Roster's FILTER state, and only that. Its column toggles and
  // question picker are display state, they live in localStorage per browser,
  // and a shared view that overwrote them would take a colleague's chosen
  // columns away when they opened someone else's saved filter.
  roster: ["section_name", "status"],
};
// Relative ranges a view of this report may STORE. Same vocabulary the email
// subscriptions use (getDateRange), so a view could later feed one unchanged.
// `last7` stays accepted for gl though it is not offered: views saved before it
// was dropped still hold it, and it resolves identically to prior7.
const SAVED_VIEW_RELATIVE_ACCEPT = {
  gl:     ["today", "yesterday", "prior7", "prior30", "last7", "lastMonth"],
  roster: ["today", "next7", "next14", "next30", "prior7", "prior30", "lastMonth"],
};
// What a page OFFERS, in the order it offers them — injected into ORG_CONFIG so
// the save dialog cannot offer a range the server then refuses. It could: gl.html
// carried a hardcoded list that included "Today", which REPORT_BLOCKED_RANGES has
// always rejected, so every attempt to save that view failed with a message
// about 7am email sends. One list, server-side, is the fix.
//
// A ROSTER reads FORWARD — it answers "who is coming" — so its ranges lead with
// the next fortnight, the report's own default window. The backward ones follow
// because a past camp's roster is a real question, just not the common one. GL is
// the opposite and only looks back; REPORT_BLOCKED_RANGES already says so.
const SAVED_VIEW_RELATIVE_OFFER = {
  gl: [
    ["lastMonth", "Last month"],
    ["prior30",   "Prior 30 days"],
    ["prior7",    "Prior 7 days"],
    ["yesterday", "Yesterday"],
  ],
  roster: [
    ["next14",   "Next 14 days"],
    ["next7",    "Next 7 days"],
    ["next30",   "Next 30 days"],
    ["today",    "Today"],
    ["prior7",   "Prior 7 days"],
    ["prior30",  "Prior 30 days"],
    ["lastMonth", "Last month"],
  ],
};
const SAVED_VIEW_DATE_MODES = ["current", "relative", "fixed"];
const SAVED_VIEWS_MAX = 25;          // per org + report
const SAVED_VIEW_MAX_BYTES = 4096;   // per view, serialized
const SAVED_VIEW_TOMBSTONE_MS = 30 * 24 * 60 * 60 * 1000;
const SAVED_VIEW_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

function savedViewsGate(req, res) {
  const org = ORGS[req.params.org];
  if (!org) { res.status(404).json({ error: "Unknown org" }); return null; }
  const supplied = req.query.token || req.headers["x-token"] || (req.body && req.body.token) || "";
  if (org.token && supplied !== org.token) { res.status(403).json({ error: "Invalid token" }); return null; }
  if (!SAVED_VIEW_PARAMS[req.params.report]) {
    res.status(404).json({ error: `Saved views aren't enabled for the "${req.params.report}" report` });
    return null;
  }
  return org;
}

function readSavedViews() { return readJSON(SAVED_VIEWS_FILE, {}); }
function listSavedViews(all, org, report) {
  const rows = all[org] && all[org][report];
  return Array.isArray(rows) ? rows : [];
}
const liveViews = rows => rows.filter(v => !v.deletedAt);
function writeSavedViews(all, org, report, rows) {
  // Compact tombstones on the way out — a deleted view is recoverable for 30
  // days (that's what the Undo toast restores), not forever.
  const cutoff = Date.now() - SAVED_VIEW_TOMBSTONE_MS;
  const kept = rows.filter(v => !v.deletedAt || Date.parse(v.deletedAt) > cutoff);
  if (!all[org]) all[org] = {};
  all[org][report] = kept;
  writeJSON(SAVED_VIEWS_FILE, all);
  return kept;
}
function sortViews(rows) {
  return rows.slice().sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: "base" }));
}

// `params` is the one field a client controls end-to-end AND that ends up in a
// Puppeteer URL via generatePdf, so allowlist hard: parse it, keep only the
// registered keys for this report, and drop the report plumbing outright.
function cleanViewParams(report, raw) {
  const allow = SAVED_VIEW_PARAMS[report] || [];
  const supplied = new URLSearchParams(String(raw || ""));
  const out = new URLSearchParams();
  for (const key of allow) {
    const v = supplied.get(key);
    if (v === null) continue;
    const val = String(v).trim();
    if (!val || val === "null" || val === "undefined") continue;
    out.set(key, val.slice(0, 600));
  }
  return out.toString();
}

// Build a complete stored view from a request body, falling back to `existing`
// for any field the caller left out (so PATCH can send just a name).
// Returns { view } or { error }.
function normalizeViewInput(report, body, existing) {
  const name = String(body.name !== undefined ? body.name : (existing ? existing.name : "")).trim();
  if (!name) return { error: "Give the view a name." };
  if (name.length > 60) return { error: "Name must be 60 characters or fewer." };

  const dateMode = body.dateMode !== undefined ? String(body.dateMode)
                 : (existing ? existing.dateMode : "current");
  if (!SAVED_VIEW_DATE_MODES.includes(dateMode)) {
    return { error: "dateMode must be current, relative or fixed." };
  }

  let relativeRange = null, fixedStart = null, fixedEnd = null;
  if (dateMode === "relative") {
    relativeRange = String(body.relativeRange !== undefined ? body.relativeRange
                         : (existing ? existing.relativeRange : "") || "");
    if (!(SAVED_VIEW_RELATIVE_ACCEPT[report] || []).includes(relativeRange)) {
      return { error: "Unknown date range." };
    }
    // A range that is never populated at send time is never populated on open
    // either — the same rule the email subscriptions apply.
    const why = rangeBlocked(report, relativeRange);
    if (why) return { error: why };
  }
  if (dateMode === "fixed") {
    fixedStart = String(body.fixedStart !== undefined ? body.fixedStart
                      : (existing ? existing.fixedStart : "") || "");
    fixedEnd   = String(body.fixedEnd   !== undefined ? body.fixedEnd
                      : (existing ? existing.fixedEnd : "") || "");
    if (!SAVED_VIEW_DATE_RE.test(fixedStart) || !SAVED_VIEW_DATE_RE.test(fixedEnd)) {
      return { error: "Pinned dates must both be YYYY-MM-DD." };
    }
    if (fixedStart > fixedEnd) return { error: "The start date is after the end date." };
  }

  const params = body.params === undefined
    ? (existing ? existing.params : "")
    : cleanViewParams(report, body.params);

  const view = {
    id: existing ? existing.id : "v_" + crypto.randomBytes(8).toString("hex"),
    name, dateMode, relativeRange, fixedStart, fixedEnd, params,
    owner: existing && existing.owner !== undefined ? existing.owner : null,
    createdAt: existing ? existing.createdAt : new Date().toISOString(),
    updatedAt: existing ? new Date().toISOString() : null,
    deletedAt: null,
  };
  if (JSON.stringify(view).length > SAVED_VIEW_MAX_BYTES) {
    return { error: "That view carries too many filters to save." };
  }
  return { view };
}

app.get("/:org/:report/api/views", (req, res) => {
  if (!savedViewsGate(req, res)) return;
  const rows = liveViews(listSavedViews(readSavedViews(), req.params.org, req.params.report));
  res.json({ views: sortViews(rows), max: SAVED_VIEWS_MAX,
             ranges: SAVED_VIEW_RELATIVE_OFFER[req.params.report] || [] });
});

app.post("/:org/:report/api/views", (req, res) => {
  if (!savedViewsGate(req, res)) return;
  const { org, report } = req.params;
  const body = req.body || {};
  const all = readSavedViews();
  const rows = listSavedViews(all, org, report);
  const name = String(body.name || "").trim();
  // A name collision is the "Update this view" path, but only when the client
  // says so — otherwise two people saving "Front desk" would silently clobber.
  const clash = liveViews(rows).find(v => v.name.toLowerCase() === name.toLowerCase());
  if (clash && !body.replace) {
    return res.status(409).json({ error: `A view named "${clash.name}" already exists.`, existingId: clash.id });
  }
  if (!clash && liveViews(rows).length >= SAVED_VIEWS_MAX) {
    return res.status(400).json({ error: `This report already has ${SAVED_VIEWS_MAX} saved views — delete one first.` });
  }
  const { view, error } = normalizeViewInput(report, body, clash || null);
  if (error) return res.status(400).json({ error });
  const next = clash ? rows.map(v => (v.id === clash.id ? view : v)) : rows.concat([view]);
  writeSavedViews(all, org, report, next);
  logEvent(org, report, "view-save", req, { view: view.name, dateMode: view.dateMode, replaced: !!clash });
  res.json({ ok: true, view });
});

app.patch("/:org/:report/api/views/:id", (req, res) => {
  if (!savedViewsGate(req, res)) return;
  const { org, report, id } = req.params;
  const body = req.body || {};
  const all = readSavedViews();
  const rows = listSavedViews(all, org, report);
  const idx = rows.findIndex(v => v.id === id);
  if (idx < 0) return res.status(404).json({ error: "No such view" });

  // Undo path: bring a tombstone back, subject to the same cap as a new save.
  if (body.restore) {
    if (rows[idx].deletedAt && liveViews(rows).length >= SAVED_VIEWS_MAX) {
      return res.status(400).json({ error: `This report already has ${SAVED_VIEWS_MAX} saved views — delete one first.` });
    }
    const restored = Object.assign({}, rows[idx], { deletedAt: null });
    rows[idx] = restored;
    writeSavedViews(all, org, report, rows);
    logEvent(org, report, "view-restore", req, { view: restored.name });
    return res.json({ ok: true, view: restored });
  }

  if (rows[idx].deletedAt) return res.status(404).json({ error: "That view was deleted" });
  const name = body.name !== undefined ? String(body.name).trim() : rows[idx].name;
  const clash = liveViews(rows).find(v => v.id !== id && v.name.toLowerCase() === name.toLowerCase());
  if (clash) return res.status(409).json({ error: `A view named "${clash.name}" already exists.` });
  const { view, error } = normalizeViewInput(report, body, rows[idx]);
  if (error) return res.status(400).json({ error });
  rows[idx] = view;
  writeSavedViews(all, org, report, rows);
  logEvent(org, report, "view-save", req, { view: view.name, dateMode: view.dateMode, updated: true });
  res.json({ ok: true, view });
});

// Soft delete — the list is shared, so a mis-click has to be recoverable.
app.delete("/:org/:report/api/views/:id", (req, res) => {
  if (!savedViewsGate(req, res)) return;
  const { org, report, id } = req.params;
  const all = readSavedViews();
  const rows = listSavedViews(all, org, report);
  const idx = rows.findIndex(v => v.id === id && !v.deletedAt);
  if (idx < 0) return res.status(404).json({ error: "No such view" });
  const gone = Object.assign({}, rows[idx], { deletedAt: new Date().toISOString() });
  rows[idx] = gone;
  writeSavedViews(all, org, report, rows);
  logEvent(org, report, "view-delete", req, { view: gone.name });
  res.json({ ok: true, view: gone });
});


// ── Per-org report settings ──────────────────────────────────────────────────
// A report's DEFAULTS, per org: what it opens on, how fresh its data is, and how
// its exports are shaped. Registry-driven exactly like SAVED_VIEW_PARAMS — only
// `roster` is registered, and every other report 404s until someone asks for it.
//
// THREE THINGS THIS IS NOT, each of which would be a different feature:
//
//  1. NOT an override. A setting seeds the FIRST load; a reader's own column
//     toggles still win afterwards and still persist in their browser. If a
//     saved default reached in and reset those, the first support ticket would
//     be "my settings keep resetting" — which is exactly why columns were kept
//     out of saved views.
//  2. NOT a saved view. A view is a named filter set anyone can make, many per
//     report. This is one starting point per org.
//  3. NOT access control. Single tenant today (Dan, 2026-08-27: "anyone can edit
//     the settings, we'll figure out a multi tenant thing later"), so the gate is
//     the org token the report link already carries — the same reach as the
//     saved-views API beside it. When multi-tenant lands this is the one place
//     that needs a role check.
const REPORT_SETTINGS_FILE = path.join(DATA_DIR, "report-settings.json");

// The Class Roster's twelve column toggles, with the defaults the page ships.
// Keys match `cols` in public/roster.html — the spec fails if the two drift.
const ROSTER_COL_DEFAULTS = {
  recId: false, dob: false, age: true, grade: true, gender: false,
  contact: true, owner: true, ownerContact: false,
  emergency: true, pickup: true, registered: false, responses: false,
};
// Controls an org can remove from the toolbar. OFF removes, it does not disable:
// a greyed button that never works is worse than no button (the ePACT one also
// 404s its beacon, the same shape as MUNIS_EXPORT_ORGS).
// NOT in this list: email subscriptions. The roster is not in
// EMAIL_SUBSCRIBABLE_REPORTS (only `facility` and `gl` are), so it has no
// subscribe control to remove — and a switch over a control that does not exist
// is the same dead end as a greyed button. It belongs here the day the roster
// becomes subscribable, or the day this panel reaches gl/facility.
const ROSTER_HIDEABLE = ["questions", "views", "pdf", "print", "excel", "epact"];

// Which roster fields an ePACT column may be built from, and how each is read.
// PARTICIPANT- and SECTION-grain only, and that restriction is load-bearing:
// the export reproduces her SELECT DISTINCT over the chosen columns, so adding a
// SESSION-grain field (Session Start / Session End) would stop the dedupe
// collapsing two same-day sessions and upload the same camper twice. Those two
// fields are therefore absent from this catalogue on purpose.
const EPACT_FIELD_CATALOGUE = [
  ["Rec ID",                      "recId"],
  ["First Name",                  "firstName"],
  ["Last Name",                   "lastName"],
  ["Household Owner Email",       "email"],        // COALESCE(participant, owner)
  ["Session Date - Section Name", "__label"],      // built by epactLabel()
  ["Date of Birth",               "dob"],
  ["Age",                         "age"],
  ["Grade",                       "grade"],
  ["Gender",                      "gender"],
  ["Phone",                       "phone"],
  ["Household Owner",             "owner"],
  ["Owner Email",                 "ownerEmail"],   // owner.email ALONE — not hers
  ["Owner Phone",                 "ownerPhone"],
  ["Section",                     "section"],
  ["Class",                       "className"],
  ["Session Date",                "sessionDate"],
];
// The five verified against her Metabase query — 68 rows, byte-identical, same
// order (apex, "After School Care - Hackberry Hill", 2026-08-27). Deviating is
// allowed and must never be silent; the page says so on screen.
const EPACT_VERIFIED_COLUMNS = [
  "Rec ID", "First Name", "Last Name", "Household Owner Email",
  "Session Date - Section Name",
];

// A cache floor. Below this a "setting" stops being a preference and becomes a
// load decision: the roster runs on a card EVERY org shares, so one org at 5
// minutes spends everyone's Metabase budget. 30 minutes is the same order as
// GL's 15, which is deliberate and carries an on-screen freshness stamp.
const REPORT_TTL_FLOOR_MIN = 30;
const REPORT_TTL_CEILING_MIN = 24 * 60;

// ── The shared-card budget ───────────────────────────────────────────────────
// A per-org floor alone does not answer Dan's objection ("can't have one org
// going rogue and borking it for everyone"), because the floor is per org and
// the CARD is shared: every org's roster comes off the same Metabase card, so
// each org that shortens its cache adds its own queries to one queue. The
// failure mode is contention, and this repo has already had it — the post-deploy
// prewarm storm that 502'd the facility Summary.
//
// So the budget is platform-wide, expressed as a MULTIPLE of what every org
// sitting on the shipping default would cost. Written that way rather than as a
// fixed number so it cannot go stale as orgs are onboarded.
const REPORT_BUDGET_MULTIPLE = 2;

// What a report's shared card is scheduled to cost per day, org by org.
// `overrideOrg`/`overrideTtlMin` model a change BEFORE it is saved, which is
// what lets the panel price a drag and the route refuse one.
function sharedCardLoad(rt, overrideOrg, overrideTtlMin) {
  const def = reportSettingsDefaults(rt).cacheTtlMin;
  const perDay = ttl => Math.round(24 * 60 / Math.max(1, ttl));
  const rows = [];
  for (const slug of Object.keys(ORGS)) {
    // Only orgs that can actually open the report spend anything on its card.
    let visible = true;
    try { visible = visibleReportsForOrg(slug).includes(rt); } catch (_) {}
    if (!visible) continue;
    const ttl = (slug === overrideOrg && overrideTtlMin) ? overrideTtlMin
              : reportSettings(slug, rt).cacheTtlMin;
    rows.push({ org: slug, ttlMin: ttl, perDay: perDay(ttl) });
  }
  const total = rows.reduce((a, r) => a + r.perDay, 0);
  const baseline = rows.length * perDay(def);
  return {
    orgs: rows.length,
    total,
    baseline,
    budget: baseline * REPORT_BUDGET_MULTIPLE,
    // Who is actually spending more than the default, worst first — so a refusal
    // can name them instead of blaming whoever happened to drag the slider last.
    heaviest: rows.filter(r => r.ttlMin < def).sort((a, b) => b.perDay - a.perDay)
                  .slice(0, 5).map(r => ({ org: r.org, ttlMin: r.ttlMin, perDay: r.perDay })),
  };
}

const REPORT_SETTINGS_SCHEMA = {
  roster: {
    // ── what it opens on ──
    // Over ~30 days the roster prints a block per session date and the query
    // widens with it — a month at Apex was ~382 pages and 12,130 rows before the
    // reader had chosen anything. Allowed, but the panel says so.
    defaultDays:   { kind: "int",  min: 1, max: 366, def: 14, warnAbove: 30 },
    defaultStatus: { kind: "enum", values: ["all", "enrolled", "cancelled"], def: "all" },
    autoRun:       { kind: "bool", def: true },
    cols:          { kind: "flags", keys: Object.keys(ROSTER_COL_DEFAULTS), def: ROSTER_COL_DEFAULTS },
    hide:          { kind: "flags", keys: ROSTER_HIDEABLE, def: {} },
    // ── how fresh ──
    cacheTtlMin:   { kind: "int",  min: REPORT_TTL_FLOOR_MIN, max: REPORT_TTL_CEILING_MIN, def: 120 },
    showStamp:     { kind: "bool", def: false },
    // Warm the window the PAGE will actually ask for. Default OFF: it adds a
    // Metabase query per org per day, so it is opt-in and measurable rather
    // than a silent load increase. See the note in prewarmCache().
    warmDefaultWindow: { kind: "bool", def: false },
    // ── exports ──
    epactColumns:  { kind: "columns", catalogue: EPACT_FIELD_CATALOGUE.map(c => c[0]),
                     min: 1, max: 12, def: EPACT_VERIFIED_COLUMNS },
    epactLabel:    { kind: "enum", values: ["date-section", "section", "section-date"], def: "date-section" },
    epactBom:      { kind: "bool", def: true },
  },
};

function reportSettingsEnabled(report) { return !!REPORT_SETTINGS_SCHEMA[report]; }

// ── Who may touch these ──────────────────────────────────────────────────────
// TWO gates, and both are deliberate.
//
//  1. The `reportSettings` feature flag, default OFF.
//  2. A super-admin key, which is NOT the org token: every staffer at an org has
//     that, and these settings change what all of them see plus what the shared
//     card costs. It is derived from DASHBOARD_PASSWORD rather than being the
//     password, so it can sit in a URL without handing over the admin dashboard,
//     and rotating the password rotates it.
//
// FAILS CLOSED. No DASHBOARD_PASSWORD means no key, which means nobody can open
// the panel — not "open access", which is what dashboardAuth does for the root
// page. The failure direction for a control that spends a shared resource has to
// be locked, not open.
function reportSettingsAdminKey() {
  if (!DASHBOARD_PASSWORD) return "";
  return crypto.createHash("sha256")
    .update(DASHBOARD_PASSWORD + "|report-settings|v1").digest("hex").slice(0, 32);
}
function reportSettingsKeyMatches(got, want) {
  if (!want || String(got).length !== want.length) return false;
  try {
    return crypto.timingSafeEqual(Buffer.from(String(got)), Buffer.from(want));
  } catch (_) { return false; }
}
// Three ways in, one credential. The COOKIE is the ordinary one — signing into
// the admin dashboard sets it, so navigating to an org report just works. The
// query parameter and the header stay for a link someone was handed and for the
// specs, which drive the routes without a browser.
function reportSettingsKeyOk(req) {
  const want = reportSettingsAdminKey();
  if (!want) return false;
  const offered = [
    req.query && req.query.admin,
    req.headers && req.headers["x-admin-key"],
    readCookie(req, RS_ADMIN_COOKIE),
  ];
  return offered.some(v => v && reportSettingsKeyMatches(v, want));
}
function isReportSettingsAdmin(req) {
  return !!getFlags().reportSettings && reportSettingsKeyOk(req);
}
// A PROVEN super-admin with the feature switched off is a different state from
// an org staffer, and rendering both as "no gear" is what made this look broken:
// you sign in, navigate to the report, and nothing tells you the switch exists.
// Absent-not-greyed is the rule for someone who may never have the control; for
// someone who holds the credential it is a dead end with no exit.
function reportSettingsFlagOff(req) {
  return !getFlags().reportSettings && reportSettingsKeyOk(req);
}

function reportSettingsDefaults(report) {
  const schema = REPORT_SETTINGS_SCHEMA[report];
  if (!schema) return {};
  const out = {};
  for (const [k, f] of Object.entries(schema)) {
    out[k] = f.kind === "flags" ? Object.assign({}, f.def)
           : f.kind === "columns" ? f.def.slice()
           : f.def;
  }
  return out;
}

// Memoised: reportTtlMs() runs on every cache read and sweep, so a synchronous
// disk read per call would put file I/O on the hot path. Invalidated on write,
// so a saved setting takes effect immediately rather than after a timeout.
let _rsStore = null;
function readReportSettingsStore() {
  if (_rsStore === null) _rsStore = readJSON(REPORT_SETTINGS_FILE, {});
  return _rsStore;
}
function writeReportSettingsStore(all) {
  writeJSON(REPORT_SETTINGS_FILE, all);
  _rsStore = all;
}

// The merged view: platform defaults with the org's stored overrides on top.
// Every reader goes through this, so a missing file, a partial record and a key
// the schema has since dropped all resolve to the shipping default rather than
// to undefined.
function reportSettings(orgSlug, report) {
  const defaults = reportSettingsDefaults(report);
  if (!REPORT_SETTINGS_SCHEMA[report]) return defaults;
  const stored = (readReportSettingsStore()[orgSlug] || {})[report];
  if (!stored || typeof stored !== "object") return defaults;
  const clean = normalizeReportSettings(report, stored);
  return Object.assign(defaults, clean.settings || {});
}

// Validate a submitted patch against the schema, field by field. Returns
// { settings } with only recognised, in-range keys, plus `dropped` naming what
// was refused — a settings PUT that silently discards a field looks like a
// working control and is not one.
function normalizeReportSettings(report, body) {
  const schema = REPORT_SETTINGS_SCHEMA[report];
  if (!schema) return { error: `Settings aren't enabled for the "${report}" report` };
  if (!body || typeof body !== "object") return { error: "Expected a settings object." };
  const out = {}, dropped = [];
  for (const [key, val] of Object.entries(body)) {
    const f = schema[key];
    if (!f) { dropped.push(key + " (unknown)"); continue; }
    if (f.kind === "bool") {
      if (typeof val !== "boolean") { dropped.push(key + " (not a boolean)"); continue; }
      out[key] = val;
    } else if (f.kind === "int") {
      const n = Number(val);
      if (!Number.isFinite(n)) { dropped.push(key + " (not a number)"); continue; }
      // Clamped, not refused: a slider that snaps to the floor teaches the limit,
      // where an error just loses the edit.
      out[key] = Math.min(f.max, Math.max(f.min, Math.round(n)));
    } else if (f.kind === "enum") {
      if (!f.values.includes(val)) { dropped.push(key + " (not one of " + f.values.join("/") + ")"); continue; }
      out[key] = val;
    } else if (f.kind === "flags") {
      if (!val || typeof val !== "object") { dropped.push(key + " (not an object)"); continue; }
      const flags = {};
      for (const k of f.keys) if (typeof val[k] === "boolean") flags[k] = val[k];
      out[key] = Object.assign(Object.assign({}, f.def), flags);
    } else if (f.kind === "columns") {
      if (!Array.isArray(val)) { dropped.push(key + " (not a list)"); continue; }
      const seen = new Set();
      const cols = val.filter(c => typeof c === "string" && f.catalogue.includes(c)
                                   && !seen.has(c) && seen.add(c));
      if (cols.length < f.min) { dropped.push(key + " (needs at least " + f.min + " column)"); continue; }
      out[key] = cols.slice(0, f.max);
    }
  }
  return { settings: out, dropped };
}

// Is this org's ePACT column set still the one verified against her query?
// Order matters — ePACT maps on position as well as header.
function epactIsVerified(cols) {
  return Array.isArray(cols) && cols.length === EPACT_VERIFIED_COLUMNS.length
      && cols.every((c, i) => c === EPACT_VERIFIED_COLUMNS[i]);
}

// The TTL for one org's feed. Replaces every `REPORT_CACHE_TTL[rt] || CACHE_TTL`
// so a per-org override cannot be honoured in one place and ignored in another —
// a cache read and a cache sweep disagreeing about a TTL is how an entry becomes
// unreachable but resident.
function reportTtlMs(orgSlug, rt, hist) {
  if (hist) return HIST_CACHE_TTL;
  if (rt === "users") return USERS_CACHE_TTL;
  const base = REPORT_CACHE_TTL[rt] || CACHE_TTL;
  if (!orgSlug || !reportSettingsEnabled(rt)) return base;
  const min = reportSettings(orgSlug, rt).cacheTtlMin;
  return Number.isFinite(min) ? min * 60 * 1000 : base;
}
// Cache keys are `org:report:...`, so the org is always recoverable from one.
// A function DECLARATION, not a const arrow: every caller sits hundreds of lines
// above this and a const would be in its temporal dead zone the moment one of
// them ran during module init.
function ttlForKey(key, rt, hist) {
  return reportTtlMs(String(key || "").split(":")[0], rt, hist);
}

// The key, for the one person allowed to have it. Behind DASHBOARD_PASSWORD, so
// knowing the password is what gets you the key rather than the key being the
// password — a URL carrying this cannot open the admin dashboard.
app.get("/api/admin/report-settings-key", (req, res) => {
  if (!DASHBOARD_PASSWORD) {
    return res.status(503).json({ error: "Set DASHBOARD_PASSWORD in Railway to enable report settings" });
  }
  const auth = req.headers["authorization"] || "";
  const basic = auth.startsWith("Basic ")
    ? (d => d.includes(":") ? d.split(":").slice(1).join(":") : d)(Buffer.from(auth.slice(6), "base64").toString("utf-8"))
    : "";
  const pw = req.query.password || (req.body && req.body.password) || basic;
  if (pw !== DASHBOARD_PASSWORD) return res.status(403).json({ error: "Wrong password" });
  res.json({
    enabled: !!getFlags().reportSettings,
    key: reportSettingsAdminKey(),
    usage: "sign in to this dashboard and the gear appears on the reports you navigate to; " +
           "&admin=<key> on a report URL is the fallback for a link you were handed",
  });
});

app.get("/:org/:report/api/settings", (req, res) => {
  const { org, report } = req.params;
  if (!ORGS[org]) return res.status(404).json({ error: "Unknown org" });
  const supplied = req.query.token || req.headers["x-token"] || "";
  if (ORGS[org].token && supplied !== ORGS[org].token) return res.status(403).json({ error: "Invalid token" });
  // 404 rather than 403: an org staffer with a valid token should not learn that
  // a settings surface exists at all.
  if (!isReportSettingsAdmin(req)) return refuse404(res);
  if (!reportSettingsEnabled(report)) {
    return refuse404(res, { error: `Settings aren't enabled for the "${report}" report` });
  }
  const settings = reportSettings(org, report);
  res.json({
    settings,
    defaults: reportSettingsDefaults(report),
    catalogue: { epactColumns: EPACT_FIELD_CATALOGUE.map(c => c[0]), hideable: ROSTER_HIDEABLE },
    limits: { ttlFloorMin: REPORT_TTL_FLOOR_MIN, ttlCeilingMin: REPORT_TTL_CEILING_MIN },
    epactVerified: epactIsVerified(settings.epactColumns),
    verifiedEpactColumns: EPACT_VERIFIED_COLUMNS,
    sharedCard: resolveReportCard(org, report).shared ? sharedCardLoad(report) : null,
  });
});

app.put("/:org/:report/api/settings", (req, res) => {
  const { org, report } = req.params;
  if (!ORGS[org]) return res.status(404).json({ error: "Unknown org" });
  const supplied = req.query.token || req.headers["x-token"] || (req.body && req.body.token) || "";
  if (ORGS[org].token && supplied !== ORGS[org].token) return res.status(403).json({ error: "Invalid token" });
  if (!isReportSettingsAdmin(req)) return refuse404(res);
  if (!reportSettingsEnabled(report)) {
    return refuse404(res, { error: `Settings aren't enabled for the "${report}" report` });
  }
  const body = Object.assign({}, req.body || {});
  delete body.token;
  // Reset: drop the org's record rather than writing the defaults into it, so a
  // later change to a platform default reaches an org that reset.
  if (body.reset === true) {
    const all = readReportSettingsStore();
    if (all[org]) { delete all[org][report]; writeReportSettingsStore(all); }
    logEvent(org, report, "settings-reset", req);
    return res.json({ ok: true, settings: reportSettingsDefaults(report), reset: true });
  }
  delete body.reset;
  const { settings, dropped, error } = normalizeReportSettings(report, body);
  if (error) return res.status(400).json({ error });

  // A per-org floor is not enough on a SHARED card: it bounds one org and the
  // card is spent by all of them. Refuse a change that would push the platform
  // total past its budget, and NAME who is already heavy — the org dragging the
  // slider is not necessarily the one that filled it.
  if (settings.cacheTtlMin != null && resolveReportCard(org, report).shared) {
    const now = sharedCardLoad(report);
    const next = sharedCardLoad(report, org, settings.cacheTtlMin);
    if (next.total > next.budget && next.total > now.total) {
      const who = next.heaviest.map(h => `${h.org} at ${h.ttlMin}m`).join(", ");
      return res.status(400).json({
        error: `That cache lifetime would put the shared ${report} card at ${next.total} queries/day, `
             + `over the platform budget of ${next.budget}. `
             + (who ? `Already running short: ${who}. ` : "")
             + `Lengthen another org's cache first, or leave this one at ${now.total <= now.budget ? "its current setting" : "the default"}.`,
        budget: { total: next.total, cap: next.budget, heaviest: next.heaviest },
      });
    }
  }

  const all = readReportSettingsStore();
  const before = (all[org] || {})[report] || {};
  if (!all[org]) all[org] = {};
  all[org][report] = Object.assign({}, before, settings);
  writeReportSettingsStore(all);

  const merged = reportSettings(org, report);
  // A TTL change alters the key's lifetime, not the key, so entries already
  // resident keep serving under the NEW ttl on the next read — nothing to purge.
  logEvent(org, report, "settings-save", req, {
    changed: Object.keys(settings).join(",").slice(0, 200),
    ttlMin: merged.cacheTtlMin,
    epactVerified: epactIsVerified(merged.epactColumns),
  });
  res.json({ ok: true, settings: merged, dropped,
             epactVerified: epactIsVerified(merged.epactColumns) });
});

// ── Subscription API ─────────────────────────────────────────────────
app.get("/:org/admin/reports", (req, res) => {
  const org = ORGS[req.params.org];
  if (!org) return res.status(404).json({ error: "Unknown org" });
  const reportLabels = {
    facility: "Facility Rental Schedule",
    gl:       "GL Code Rollup",
    historic: "Historic Buildings",
    programs: "Programs",
    roster:   "Class Roster",
  };
  const available = REPORT_TYPES
    .filter(r => EMAIL_SUBSCRIBABLE_REPORTS.has(r) && (org[r]?.mbUuid || SHARED_UUIDS[r]))
    .map(r => ({ key: r, label: reportLabels[r] || r }));
  res.json({ reports: available });
});

app.get("/:org/admin/subscribers", (req, res) => {
  if (!ORGS[req.params.org]) return res.status(404).json({ error: "Unknown org" });
  const rows = db.getSubscriptions(req.params.org);
  const log  = db.getLog(req.params.org);
  res.json({ subscribers: rows, log });
});

app.post("/:org/admin/subscribe", (req, res) => {
  if (!ORGS[req.params.org]) return res.status(404).json({ error: "Unknown org" });
  const { email, reports, schedule, locationFilter, dateRange, reportParams, reportDateRanges } = req.body;
  if (!email || !reports?.length || !schedule) return res.status(400).json({ error: "email, reports, and schedule are required" });
  const emailDomain = email.split("@")[1]?.toLowerCase();
  // Domain restriction removed — access is gated by EMAIL_ENABLED_ORGS + token
  if (!EMAIL_ENABLED_ORGS.has(req.params.org)) return res.status(403).json({ error: "Email subscriptions are not enabled for this organization" });
  if (!["daily","weekly","monthly"].includes(schedule)) return res.status(400).json({ error: "schedule must be daily, weekly, or monthly" });
  const validReports = reports.filter(r => REPORT_TYPES.includes(r));
  if (!validReports.length) return res.status(400).json({ error: "No valid report types" });

  const validDateRanges = VALID_DATE_RANGES;

  // The admin form doesn't offer these pairings, but the form is not the only
  // way into this route.
  const blockedPick = validReports
    .map(r => ({ report: r, why: rangeBlocked(r, (reportDateRanges && reportDateRanges[r]) || dateRange) }))
    .find(x => x.why);
  if (blockedPick) return res.status(400).json({ error: blockedPick.why });

  // Validate + sanitize reportParams (optional object keyed by report type → URL query string)
  const cleanReportParams = {};
  if (reportParams && typeof reportParams === "object" && !Array.isArray(reportParams)) {
    for (const [key, val] of Object.entries(reportParams)) {
      if (!REPORT_TYPES.includes(key)) continue;
      const out = cleanReportParamString(val);
      if (out.length) cleanReportParams[key] = out;
    }
  }

  // Clean reportDateRanges
  const cleanDateRanges = {};
  if (reportDateRanges && typeof reportDateRanges === "object") {
    for (const [k, v] of Object.entries(reportDateRanges)) {
      if (validReports.includes(k) && validDateRanges.includes(v)) cleanDateRanges[k] = v;
    }
  }
  db.upsertSubscription(
    req.params.org,
    email.toLowerCase().trim(),
    validReports,
    schedule,
    locationFilter || null,
    validDateRanges.includes(dateRange) ? dateRange : null,
    cleanReportParams,
    cleanDateRanges,
  );
  res.json({ ok: true });
});

app.delete("/:org/admin/subscribe", (req, res) => {
  if (!ORGS[req.params.org]) return res.status(404).json({ error: "Unknown org" });
  const { email, id } = req.body;
  if (!email) return res.status(400).json({ error: "email required" });
  db.deleteSubscription(req.params.org, email.toLowerCase().trim(), id || null);
  res.json({ ok: true });
});

// ── Clear send log for org (password-gated) ──
app.delete("/:org/admin/log", express.json(), (req, res) => {
  const slug = req.params.org;
  if (!ORGS[slug]) return res.status(404).json({ error: "Unknown org" });
  const { password } = req.body || {};
  if (!password || password !== process.env.DASHBOARD_PASSWORD) {
    return res.status(403).json({ error: "Invalid admin password" });
  }
  const allLog = readJSON(LOG_FILE, []);
  const kept = allLog.filter(l => l.org !== slug);
  writeJSON(LOG_FILE, kept);
  res.json({ ok: true, removed: allLog.length - kept.length });
});

app.post("/:org/admin/test-email", async (req, res) => {
  if (!ORGS[req.params.org]) return res.status(404).json({ error: "Unknown org" });
  const { email } = req.body;
  if (!email) return res.status(400).json({ error: "email required" });
  const resend = getResendClient();
  if (!resend) return res.json({ ok: false, error: "RESEND_API_KEY not configured" });
  try {
    const { data, error } = await resend.emails.send({
      from: `${FROM_NAME} <${FROM_EMAIL}>`,
      to: email,
      subject: "rec.us Report Server — Test Email",
      html: "<p>This is a test email from the rec.us report server. Resend is working!</p>",
    });
    if (error) throw new Error(JSON.stringify(error));
    console.log("[test-email] Sent to", email, data);
    res.json({ ok: true });
  } catch (err) {
    console.error("[test-email] Error:", err.message);
    res.json({ ok: false, error: err.message });
  }
});

// Send one report immediately, without waiting for a schedule. Two callers:
// the Test button beside an existing subscriber, and the Send Test button in the
// subscribe modal on a report page — where there is NO subscription yet.
//
// That second case is the whole reason this route takes overrides. Reading the
// scope only from a saved subscription would send an unfiltered, default-window
// email and report success: a test that passes without testing what is about to
// be saved is worse than no test at all. So an explicit reportParams/dateRange
// wins, and it is cleaned by the SAME helper /admin/subscribe uses, so the test
// email and the subscription that follows it are built from identical filters.
app.post("/:org/admin/test-send", async (req, res) => {
  const slug = req.params.org;
  if (!ORGS[slug]) return res.status(404).json({ error: "Unknown org" });
  const { email, report, schedule, subId } = req.body;
  if (!email || !report || !schedule) return res.status(400).json({ error: "email, report, and schedule required" });
  // A test send is an outbound email to whatever address was typed, so it gets
  // the same validation the subscribe route applies. The org gate is a no-op
  // today (EMAIL_ENABLED_ORGS is duck-typed to every known org) and is here so
  // that if it ever becomes a real allowlist, this route stops sending too
  // rather than quietly becoming the way around it.
  if (!EMAIL_ENABLED_ORGS.has(slug)) return res.status(403).json({ error: "Email subscriptions are not enabled for this organization" });
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(email).trim())) return res.status(400).json({ error: "A valid email address is required" });
  if (!REPORT_TYPES.includes(report)) return res.status(400).json({ error: "Unknown report type" });
  if (!["daily", "weekly", "monthly"].includes(schedule)) return res.status(400).json({ error: "schedule must be daily, weekly, or monthly" });

  // Look up the specific subscription by ID (or fall back to email match)
  const subs = db.getSubscriptions(slug);
  const sub = subId ? subs.find(s => String(s.id) === String(subId)) : subs.find(s => s.email === email);
  const subParams = (sub?.reportParams && typeof sub.reportParams === "object") ? (sub.reportParams[report] || null) : null;
  const subRange = (sub?.reportDateRanges && sub.reportDateRanges[report]) || sub?.dateRange || null;

  // Overrides from the modal: the filters as they stand on screen right now.
  // reportParams arrives as a plain string (this route sends one report) or as
  // the keyed object /admin/subscribe takes, so the page can hand over the same
  // shape either way.
  const rawOverride = typeof req.body.reportParams === "string"
    ? req.body.reportParams
    : (req.body.reportParams && typeof req.body.reportParams === "object" && !Array.isArray(req.body.reportParams))
      ? req.body.reportParams[report]
      : null;
  const overrideParams = rawOverride != null ? cleanReportParamString(rawOverride) : null;
  const rawRange = typeof req.body.dateRange === "string" ? req.body.dateRange
    : (req.body.reportDateRanges && typeof req.body.reportDateRanges === "object") ? req.body.reportDateRanges[report]
    : null;
  const overrideRange = VALID_DATE_RANGES.includes(rawRange) ? rawRange : null;

  const savedParams = overrideParams != null ? (overrideParams || null) : subParams;
  const dateRange = overrideRange || subRange;
  const locationFilter = sub?.locationFilter || null;

  // A GL rollup covering today leaves before the day has any postings. The
  // scheduler already refuses that pairing; a test that ignored it would send a
  // blank email and teach the reader the report is broken.
  const blocked = rangeBlocked(report, dateRange);
  if (blocked) return res.status(400).json({ error: blocked });

  res.json({
    ok: true,
    message: "Sending in background — check your inbox in a moment",
    // Echo the scope actually used, so the caller can say what it sent rather
    // than claiming a filtered test it did not run.
    scope: { report, schedule, dateRange: dateRange || null, filters: savedParams || null },
  });
  sendReportEmail(slug, email, report, schedule, locationFilter, dateRange, savedParams)
    .then(_res => logEvent(slug, report, "email", req, { email, schedule, trigger: "manual", status: _res && _res.ok ? "sent" : "error" }))
    .catch(err => console.error("[test-send] Error:", err));
});

// ── Serve HTML report pages ──────────────────────────────────────────
// Report HTML pages must always revalidate so a fresh deploy is picked up
// immediately instead of a heuristically-cached stale copy. ETag/Last-Modified
// still yield cheap 304s when the file is unchanged. (Scoped here: sits below
// the API/PDF routes, above the page handlers, so only HTML pages are affected.)
app.use((req, res, next) => {
  res.set("Cache-Control", "no-store, no-cache, must-revalidate");
  next();
});

