// ── GET /:org/facilities/api/campsites — campsite geo for the Camping tab map ──
// One entry per campsite location (an org can run several distinct campgrounds;
// campmapLocations already normalizes single-location seeds into a one-element
// list). Each location's sites merge the seed (name, area, kind, GPS, price,
// photo) with any admin-dragged position overrides — the same store the campmap
// editor and the Camping tab's embedded editor write to. Empty locations list
// when the org has no campmap seed — the tab hides its map section.
app.get("/:org/facilities/api/campsites", (req, res) => {
  const slug = req.params.org;
  const org = ORGS[slug];
  if (!org) return res.status(404).json({ error: "Unknown org" });
  const seed = CAMPMAP_SEEDS[slug];
  if (!seed) return res.json({ locations: [] });
  const locations = campmapLocations(slug, seed, org).map(loc => {
    const overrides = campmapPositions[campmapStoreKey(slug, loc.id)] || {};
    const sites = (loc.sites || []).map(s => {
      const pos = overrides[s.id] || { lat: s.lat, lng: s.lng };
      if (typeof pos.lat !== "number" || typeof pos.lng !== "number") return null;
      return {
        id: s.id, name: s.name || ("Site " + (s.n || "")), area: s.area || loc.locationName || "",
        kind: s.kind || "", lat: pos.lat, lng: pos.lng,
        price: (typeof s.price === "number") ? s.price : null, photo: s.photo || "",
      };
    }).filter(Boolean);
    // Landmarks = seed emoji landmarks (read-only). Custom admin markers are
    // separate so the Camping tab's editor can edit them (name/notes/color).
    const landmarks = (loc.landmarks || []).map(lm => ({
      e: lm.e || "📍", l: lm.l || "", lat: lm.lat, lng: lm.lng,
    })).filter(lm => typeof lm.lat === "number" && typeof lm.lng === "number");
    const markers = campmapMarkers[campmapStoreKey(slug, loc.id)] || [];
    return { id: loc.id, name: loc.locationName || "", center: loc.center, address: loc.address || "", sites, landmarks, markers };
  }).filter(l => l.sites.length);
  res.json({ locations });
});

// ── POST /:org/facilities/api/campsite-markers — custom map markers editor ──
// Token-gated; replaces the location's whole marker list. Same shape and store
// the retired campmap editor used ({id,label,text,color,lat,lng}).
app.post("/:org/facilities/api/campsite-markers", express.json(), (req, res) => {
  const slug = req.params.org;
  const org = ORGS[slug];
  if (!org) return res.status(404).json({ error: "Unknown org" });
  const token = req.query.token || (req.body && req.body.token) || "";
  if (!org.token || token !== org.token) return res.status(403).json({ error: "Forbidden — valid org token required to edit." });
  const markers = (req.body && req.body.markers) || [];
  const clean = [];
  for (const m of Array.isArray(markers) ? markers : []) {
    if (!m || typeof m.lat !== "number" || typeof m.lng !== "number") continue;
    if (Math.abs(m.lat) > 90 || Math.abs(m.lng) > 180) continue;
    clean.push({
      id: String(m.id || "").slice(0, 40) || ("m" + clean.length),
      label: String(m.label || "").slice(0, 80),
      text: String(m.text || "").slice(0, 500),
      color: /^#[0-9a-fA-F]{3,8}$/.test(m.color || "") ? m.color : "#38bdf8",
      lat: m.lat, lng: m.lng,
    });
    if (clean.length >= 100) break; // sane cap
  }
  campmapMarkers[campmapStoreKey(slug, req.query.location)] = clean;
  saveCampmapMarkers();
  logEvent(slug, "facilities", "save-campsite-markers", req, { count: clean.length });
  res.json({ ok: true, saved: clean.length });
});

// ── POST /:org/facilities/api/campsite-positions — Camping tab site editor ──
// Token-gated. Replaces the location's whole position map (the client sends
// every site), stored under the same per-location key the campmap editor used,
// so history and any not-yet-migrated data stay compatible.
app.post("/:org/facilities/api/campsite-positions", express.json(), (req, res) => {
  const slug = req.params.org;
  const org = ORGS[slug];
  if (!org) return res.status(404).json({ error: "Unknown org" });
  const token = req.query.token || (req.body && req.body.token) || "";
  if (!org.token || token !== org.token) return res.status(403).json({ error: "Forbidden — valid org token required to edit." });
  const positions = (req.body && req.body.positions) || {};
  const clean = {};
  for (const [id, p] of Object.entries(positions)) {
    if (p && typeof p.lat === "number" && typeof p.lng === "number" &&
        Math.abs(p.lat) <= 90 && Math.abs(p.lng) <= 180) {
      clean[id] = { lat: p.lat, lng: p.lng };
    }
  }
  campmapPositions[campmapStoreKey(slug, req.query.location)] = clean;
  saveCampmapPositions();
  logEvent(slug, "facilities", "save-campsite-positions", req, { count: Object.keys(clean).length });
  res.json({ ok: true, saved: Object.keys(clean).length });
});

// ── GET /:org/facilities/api/summary — Facilities hub Summary data ──
// Fetches the org-parameterized Facility Summary card (row-level facility
// reservations incl. canceled) and returns { rows } for client-side
// aggregation. Same public-card + buildMetabaseParams pattern as /api/data,
// with the shared cache (reportType "facilities") + stale fallback.
// ── GET /:org/facilities/api/campmap-activity — how campers use the public map ──
// The Camping tab's map is an admin view of a PUBLIC page, and until now the only
// place its traffic showed up was the Slack feed — which is ours, not the org's.
// This is the same events, aggregated back to the org that owns the campground.
//
// Reaching this route already requires the org token: the global gate above
// (search "do not leak existence of the org") 404s every /:org/* path without
// one, exempting only calendar, rentalcalendar and campmap. The check below is a
// backstop in case that exemption list ever grows, not the primary gate — and a
// 404 rather than a 403 is what a tokenless caller actually sees, by design.
//
// Everything here is a COUNT of non-personal events (a site opened, a book button
// clicked). Nothing identifies a camper, which is why it was safe to log in the
// first place.
app.get("/:org/facilities/api/campmap-activity", (req, res) => {
  const slug = req.params.org;
  const org = ORGS[slug];
  if (!org) return res.status(404).json({ error: "Unknown org" });
  const token = req.query.token || "";
  if (!org.token || token !== org.token) {
    return res.status(403).json({ error: "Forbidden — valid org token required." });
  }
  const days = Math.min(Math.max(parseInt(req.query.days, 10) || 30, 1), 365);
  const now = Date.now();
  const cutoff = new Date(now - days * 86400000).toISOString();
  const priorCutoff = new Date(now - days * 2 * 86400000).toISOString();

  // 2x the window, so every tile can carry a delta — same shape as the calendar
  // activity route.
  const rows = readEvents(days * 2).filter(e => e.org === slug && e.report === "campmap");
  const blank = () => ({ views: 0, sites: 0, books: 0, shares: 0, filters: 0 });
  const cur = blank(), prior = blank();
  const bookKinds = {}, shareKinds = {}, siteHits = {};

  for (const e of rows) {
    const bucket = e.ts >= cutoff ? cur : (e.ts >= priorCutoff ? prior : null);
    if (!bucket) continue;
    switch (e.event) {
      case "view":            bucket.views++; break;
      case "campmap-site":    bucket.sites++; break;
      case "campmap-book":    bucket.books++; break;
      case "campmap-share":   bucket.shares++; break;
      // Both filters answer "campers narrowed the map", so they count together —
      // splitting type from amenity would make two thin numbers out of one signal.
      case "campmap-filter":
      case "campmap-amenity": bucket.filters++; break;
      default: break;
    }
    if (bucket !== cur) continue;
    if (e.event === "campmap-book")  bookKinds[e.kind || "dated"] = (bookKinds[e.kind || "dated"] || 0) + 1;
    if (e.event === "campmap-share") shareKinds[e.kind || "link"] = (shareKinds[e.kind || "link"] || 0) + 1;
    if (e.event === "campmap-site" && e.site) siteHits[e.site] = (siteHits[e.site] || 0) + 1;
  }

  const top = Object.entries(siteHits).sort((a, b) => b[1] - a[1])[0] || null;

  // A LOG THAT DOES NOT REACH BACK 30 DAYS MUST NOT READ AS 30 DAYS OF ZEROS.
  // A fresh volume, a rotated log or a PR preview would otherwise render "0 views"
  // — which an admin reads as "nobody opens my map" rather than "we have not been
  // counting that long". So say when counting actually started and let the tab
  // label the window honestly.
  const all = readEvents(null);
  const logStartsAt = all.length ? all[0].ts : null;
  const covers = !!(logStartsAt && logStartsAt <= cutoff);

  res.json({
    days, cutoff, logStartsAt, covers,
    totals: cur, prior,
    bookKinds, shareKinds,
    topSite: top ? { name: top[0], opens: top[1] } : null,
  });
});

app.get("/:org/facilities/api/summary", async (req, res) => {
  const slug = req.params.org;
  const org  = ORGS[slug];
  if (!org) return res.status(404).json({ error: "Unknown org" });
  if (!org.orgId) return res.status(400).json({ error: "Org is not configured with an org_id" });

  logEvent(slug, "facilities", "fetch", req);

  try {
    const params  = buildMetabaseParams(req.query, "facilities", org.orgId);
    const paramStr = params.length > 0 ? `?parameters=${encodeURIComponent(JSON.stringify(params))}` : "";
    const cacheKey = `${slug}:facilities:${paramStr}`;

    if (req.query._nocache !== "1") {
      const cached = getCached(cacheKey, slug, "facilities");
      if (cached) {
        console.log(`[cache] HIT ${slug}/facilities | ${cached.rows?.length || 0} rows`);
        return res.json(cached);
      }
    }

    const url = `${METABASE_URL}/api/public/card/${FACILITIES_SUMMARY_UUID}/query/json${paramStr}`;
    console.log(`[proxy] ${slug}/facilities → ${url}`);

    const fetchStart = Date.now();
    let response, attempt = 1;
    try {
      // 120s first attempt — big orgs' summary card (SF) sits at 55-100s cold,
      // and a 60s budget was aborting queries that were about to succeed.
      response = await fetch(url, { signal: AbortSignal.timeout(120000) });
    } catch (firstErr) {
      const isTimeout = firstErr.name === "TimeoutError" || firstErr.name === "AbortError";
      if (!isTimeout) throw firstErr;
      console.log(`[proxy] ${slug}/facilities timed out — retrying with 180s timeout...`);
      attempt = 2;
      response = await fetch(url, { signal: AbortSignal.timeout(180000) });
    }
    const fetchMs = Date.now() - fetchStart;

    if (!response.ok) {
      const body = await response.text();
      console.error(`[proxy] Metabase returned ${response.status} for ${slug}/facilities after ${fetchMs}ms: ${body.slice(0, 200)}`);
      const stale = getStaleCached(slug, "facilities", cacheKey);
      if (stale) {
        console.log(`[cache] STALE fallback for ${slug}/facilities`);
        return res.json(Object.assign({}, stale.data, { meta: Object.assign({}, stale.data.meta, { stale_cache: true }) }));
      }
      return res.status(502).json({ error: `Metabase ${response.status}` });
    }

    const data = await response.json();
    const rows = Array.isArray(data) ? data : [];
    console.log(`[proxy] ${slug}/facilities → ${rows.length} rows in ${fetchMs}ms (attempt ${attempt})`);

    const result = { rows, meta: { org_slug: slug, org_id: org.orgId, report_type: "facilities", generated_at: new Date().toISOString() } };
    setCache(cacheKey, result, "facilities");
    res.json(result);
  } catch (err) {
    const isTimeout = err.name === "TimeoutError" || err.name === "AbortError";
    console.error(`[proxy] ${slug}/facilities error${isTimeout ? " (timeout)" : ""}: ${err.message}`);
    const cacheKey = (() => { try { const p = buildMetabaseParams(req.query, "facilities", org.orgId); return `${slug}:facilities:${p.length ? `?parameters=${encodeURIComponent(JSON.stringify(p))}` : ""}`; } catch { return `${slug}:facilities:`; } })();
    const stale = getStaleCached(slug, "facilities", cacheKey);
    if (stale) return res.json(Object.assign({}, stale.data, { meta: Object.assign({}, stale.data.meta, { stale_cache: true }) }));
    res.status(isTimeout ? 504 : 502).json({ error: isTimeout ? "Facility summary query timed out — try a shorter date range" : err.message });
  }
});

