// ── GET /:org/facility/api/permits — which rows have an issued permit ───────
// Loaded once per view of the schedule, AFTER the rows render, so the main feed
// keeps its current speed. Returns a thin map, not the whole permit: the chip
// only needs a link and a code.
// ── GET /:org/facility/api/forms — which rows have Required Information ─────
// A thin { resId: formCount } map, loaded after the rows render like permits, so
// the schedule keeps its speed and a slow forms card can never delay it.
app.get("/:org/facility/api/forms", async (req, res) => {
  const slug = req.params.org;
  const org = ORGS[slug];
  if (!org) return res.status(404).json({ error: "Unknown org" });
  // Unset env ⇒ the column never appears, same contract as MB_GL_DETAIL_UUID.
  if (!FORMS_UUID) return res.json({ forms: {}, disabled: true });
  try {
    const counts = await fetchFormCounts(org.orgId);
    res.json({ forms: counts, count: Object.keys(counts).length });
  } catch (err) {
    console.warn(`[forms] ${slug} count feed failed: ${err.message}`);
    // Soft-fail: a schedule with no Forms column is degraded, not broken.
    res.json({ forms: {}, error: true });
  }
});

app.get("/:org/facility/api/permits", async (req, res) => {
  const slug = req.params.org;
  const org = ORGS[slug];
  if (!org) return res.status(404).json({ error: "Unknown org" });
  if (!PERMITS_UUID) return res.json({ permits: {} });
  try {
    const byRes = await fetchPermits(org.orgId);
    const permits = {};
    for (const [resId, r] of byRes) {
      permits[resId] = {
        code: r["Permit Code"] || "",
        url: r["Permit URL"] || "",
        // `id` and `multi` exist so the toolbar can count SHEETS rather than
        // rows. A multi-day permit occupies one row per calendar day in the
        // feed but prints one sheet, so a straight row count told you
        // "Export Permits (7)" and then handed you 3. The client applies the
        // same permit+site collapse this route does — keep the two in step.
        id: r["Permit ID"] || r["Permit Code"] || "",
        multi: Number(r["Date Count"] || 0) > 1,
      };
    }
    res.json({ permits, count: Object.keys(permits).length });
  } catch (err) {
    console.warn(`[permits] ${slug} chip feed failed: ${err.message}`);
    // Soft-fail: no chips is a degraded schedule, not a broken one.
    res.json({ permits: {}, error: true });
  }
});

// ── POST /:org/facility/permits.pdf — printable posting sheets ──────────────
// One page per rental-day in the CURRENT FILTERED VIEW. The client posts the
// rows it is showing, which is the only way the export can honour on-screen
// filters; the permit half is re-fetched live here so a revoked permit can
// never be printed onto a sheet that ends up taped to a fence.
app.post("/:org/facility/permits.pdf", express.json({ limit: "2mb" }), async (req, res) => {
  const slug = req.params.org;
  const org = ORGS[slug];
  if (!org) return res.status(404).type("text/plain").send("Not found");
  if (!PERMITS_UUID) return res.status(503).type("text/plain").send("Permit card is not configured yet.");

  const rows = Array.isArray(req.body && req.body.rows) ? req.body.rows.slice(0, 400) : [];
  if (!rows.length) return res.status(400).type("text/plain").send("No rows to print.");

  try {
    const byRes = await fetchPermits(org.orgId, { live: true });
    const logo = await orgLogoDataUri(slug);
    const tyler = getTylerConfig(slug) || {};
    const orgName = tyler.entityName || org.displayName
      || (slug.charAt(0).toUpperCase() + slug.slice(1) + " Parks & Recreation");
    const dept = tyler.department || "Parks & Recreation Department";

    // ONE SHEET PER PERMIT PER SITE, not per row, once a permit is multi-date.
    // A recurring rental appears in the filtered view once per date, and a
    // multi-date sheet already carries the whole run — printing it per row would
    // hand a crew ten identical pages for one fence post. Single-date permits
    // are untouched (they only ever have one row per site anyway). Where rows
    // collapse, the earliest date in view wins, since the sheet goes up at the
    // start of the run.
    const normSite = v => String(v == null ? "" : v).replace(/\s+/g, " ").trim().toLowerCase();
    const picked = [];
    const seen = new Map();
    for (const r of rows) {
      const p = byRes.get(String(r.resId || ""));
      if (!p) continue;                     // no issued permit → no sheet
      if (!p["Permit URL"]) continue;
      const key = Number(p["Date Count"] || 0) > 1
        ? `${p["Permit ID"] || p["Permit Code"]}|${normSite(r.site)}`
        : null;
      if (key && seen.has(key)) {
        const i = seen.get(key);
        if (String(r.date || "") < String(picked[i].r.date || "")) picked[i] = { r, p };
        continue;
      }
      if (key) seen.set(key, picked.length);
      picked.push({ r, p });
    }

    const QRCode = require("qrcode");
    const sheets = [];
    for (const { r, p } of picked) {
      const url = p["Permit URL"];
      sheets.push({
        org: orgName, dept, logo,
        title: r.title || p["Rental Name"] || "Facility Rental",
        holder: p["Permit Holder"] || r.reservee || "",
        site: r.site || "", location: r.location || "",
        date: r.date, begin: r.begin, end: r.end,
        headcount: r.headcount || p["Attendees"] || "",
        capacity: p["Capacity"] || "",
        addons: p["Add Ons"] || "",
        purpose: p["Purpose"] || "",
        code: p["Permit Code"] || "",
        // The permit's whole run. lib/permit scopes it to this sheet's site and
        // only renders it when there is more than one date — a single-date
        // permit sends no schedule at all (see sql/facility-permits.sql).
        schedule: p["Schedule"] || null,
        qr: await QRCode.toDataURL(url, { errorCorrectionLevel: "M", margin: 1, width: 300 }),
      });
    }
    if (!sheets.length) {
      return res.status(404).type("text/plain")
        .send("None of the rentals in this view have an issued permit.");
    }

    logEvent(slug, "facility", "permits", req, {
      sheets: sheets.length, rows: rows.length,
      multi: sheets.filter(x => x.schedule).length,
    });
    const pdf = await renderHtmlPdf(permitLib.toHtml(sheets), { landscape: false, plain: true });
    const day = (rows[0] && rows[0].date ? String(rows[0].date) : new Date().toISOString().slice(0, 10)).replace(/-/g, "");
    res.setHeader("Content-Type", "application/pdf");
    res.setHeader("Content-Disposition", `attachment; filename="${slug}-permits-${day}.pdf"`);
    res.send(pdf);
  } catch (err) {
    console.error(`[permits] ${slug} export failed: ${err.message}`);
    res.status(502).type("text/plain").send("Could not build the permit sheets.");
  }
});

// ── GET /:org/gl/tyler.:fmt — Munis "GL Account Detail" export ───────────────
// pdf  → the print-style account detail (program glgatddt), Courier, landscape
// csv  → the flat file, column order fixed by the format contract
//
// Behind the org token gate like every other /:org/ path. Enabled per org
// (MUNIS_EXPORT_ORGS) because the layout is a municipal GL form — an org
// without a real general ledger has no use for it and shouldn't see the button.
app.get("/:org/gl/tyler.:fmt", async (req, res) => {
  const slug = req.params.org;
  const fmt  = String(req.params.fmt || "").toLowerCase();
  const org  = ORGS[slug];
  if (!org) return res.status(404).type("text/plain").send("Not found");
  if (!MUNIS_EXPORT_ORGS.has(slug)) return res.status(404).type("text/plain").send("Not found");
  // Format check before the config check: an unknown extension is a 404 whether
  // or not the card happens to be wired up yet.
  if (fmt !== "pdf" && fmt !== "csv") return res.status(404).type("text/plain").send("Not found");
  if (!GL_DETAIL_UUID) {
    return res.status(503).type("text/plain").send("GL detail card is not configured yet — set MB_GL_DETAIL_UUID.");
  }

  const startDate = parseToISO(req.query.start_date) || null;
  const endDate   = parseToISO(req.query.end_date)   || null;

  try {
    const rows = await fetchGlDetailRows(org.orgId, startDate, endDate);
    const stampDay = (endDate || new Date().toISOString().slice(0, 10)).replace(/-/g, "");
    const filename = `${slug}-gl-account-detail-${stampDay}.${fmt}`;
    const un = munis.unmappedSummary(rows);
    logEvent(slug, "gl", "munis", req, { fmt, rows: rows.length, unmapped: un.count });

    if (fmt === "csv") {
      res.setHeader("Content-Type", "text/csv; charset=utf-8");
      res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
      return res.send(munis.toCsv(rows));
    }

    const tyler = getTylerConfig(slug) || {};
    const html = munis.toHtml(rows, {
      entity:     tyler.entityName || org.displayName || slug,
      department: tyler.department || "Parks & Recreation Department",
      fromDate:   startDate,
      toDate:     endDate,
      fiscalYear: munis.fiscalYearOf(endDate || new Date().toISOString().slice(0, 10), tyler.fiscalYearStartMonth) || "",
      user:       "rec.us",
      generatedAt: new Date(),
    });
    const pdf = await renderHtmlPdf(html);
    res.setHeader("Content-Type", "application/pdf");
    res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
    return res.send(pdf);
  } catch (err) {
    console.error(`[munis] ${slug} ${fmt} export failed: ${err.message}`);
    // Never echo the Metabase URL or card id back to the browser.
    return res.status(502).type("text/plain").send("Could not build the GL Account Detail export. Try a shorter date range.");
  }
});

