// ── POST /:org/rentalcalendar/api/pin — drag-to-place a location pin ──
// Token-gated (same bar as the campsite marker editor). Body: {locationId, lat, lng}.
// Sending lat/lng as null clears the override and reverts to the committed seed.
app.post("/:org/rentalcalendar/api/pin", express.json(), (req, res) => {
  const slug = req.params.org;
  const org = ORGS[slug];
  if (!org) return res.status(404).json({ error: "Unknown org" });
  const token = req.query.token || (req.body && req.body.token) || "";
  if (!org.token || token !== org.token) return res.status(403).json({ error: "Forbidden — valid org token required to move pins." });
  const { locationId } = req.body || {};
  if (!locationId || typeof locationId !== "string") return res.status(400).json({ error: "locationId required" });
  if (!rentalMapPositions[slug]) rentalMapPositions[slug] = {};
  if (req.body.lat === null || req.body.lng === null) {
    delete rentalMapPositions[slug][locationId];
  } else {
    const lat = Number(req.body.lat), lng = Number(req.body.lng);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return res.status(400).json({ error: "lat/lng must be numbers" });
    if (lat < -90 || lat > 90 || lng < -180 || lng > 180) return res.status(400).json({ error: "lat/lng out of range" });
    rentalMapPositions[slug][locationId] = { lat, lng };
  }
  saveRentalMapPositions();
  console.log(`[rentalmap] ${slug} pin ${locationId} ${req.body.lat === null ? "reset to seed" : "moved"}`);
  res.json({ ok: true, pins: rentalMapPins(slug) });
});

// ── Interactive campsite map (public, no token) ──
// Leaflet map of a campground's sites with a per-night availability overlay.
// Site data is baked into the page (incl. coords); availability upgrades to live
// data via the existing /:org/rentalcalendar/api/availability-batch endpoint.
// Normalize a campmap seed into a list of locations. Backward compatible: a flat
// single-location seed (the current shape for every existing org) becomes one
// "default" location, so behavior/stored data for those orgs is unchanged.
function campmapLocations(slug, seed, org) {
  if (seed && Array.isArray(seed.locations) && seed.locations.length) {
    return seed.locations.map((l, i) => ({
      id: String(l.id || ("loc" + (i + 1))),
      locationName: l.locationName || l.name || ("Location " + (i + 1)),
      center: l.center || null,
      address: l.address || "",
      sites: l.sites || null,
      defaults: l.defaults || {},
      areaDefaults: l.areaDefaults || {},
      landmarks: l.landmarks || null,
    }));
  }
  return [{
    id: "default",
    locationName: (seed && seed.locationName) || org.campLocationName || "",
    center: (seed && seed.center) || org.coords || null,
    address: (seed && seed.address) || org.campAddress || "",
    sites: (seed && seed.sites) || null,
    defaults: (seed && seed.defaults) || {},
    areaDefaults: (seed && seed.areaDefaults) || {},
    landmarks: (seed && seed.landmarks) || null,
  }];
}
// Storage key for admin-saved positions/markers. The default (single) location keeps
// the flat per-slug key so existing saved data is preserved; extra locations namespace.
function campmapStoreKey(slug, locationId) {
  return (!locationId || locationId === "default") ? slug : (slug + "::" + locationId);
}

// ── Standalone /:org/campmap page ──
// Public campsite-map viewer for direct-link / QR-code sharing (customers, no
// token) — the org's campmap seed, admin-saved pin positions, and custom markers
// on a Leaflet map with a per-night availability overlay (live data via
// /:org/rentalcalendar/api/availability-batch + /api/sites).
// Editing (drag-to-place pins, add/name/color/delete custom markers) is unlocked
// ONLY when the org token is supplied (?token=…) — admin-only for now, customers
// get the read-only view. Edits save through the token-gated POST endpoints below
// and write to the SAME per-location store as the Facilities Camping tab
// (campmapPositions / campmapMarkers via campmapStoreKey), so the two stay in sync.
app.get("/:org/campmap", (req, res) => {
  const slug = req.params.org;
  const org = ORGS[slug];
  if (!org) return res.status(404).send("Unknown org");
  if (!org.orgId) return res.status(404).send("Campsite map requires orgId configuration.");
  logEvent(slug, "campmap", "view", req);
  const slugTitle = slug.charAt(0).toUpperCase() + slug.slice(1);
  const seed = CAMPMAP_SEEDS[slug] || {};
  const locList = campmapLocations(slug, seed, org);
  const activeId = req.query.location || (locList[0] && locList[0].id) || "default";
  const active = locList.find(l => l.id === activeId) || locList[0] || {};
  // Normalize center to {lat, lon} — seed centers store `lng`, org.coords stores
  // `lon`; the page reads `.lon` (map center + weather lookup).
  const rawCoords = active.center || org.coords || null;
  const coords = rawCoords
    ? { lat: rawCoords.lat, lon: (rawCoords.lon != null ? rawCoords.lon : rawCoords.lng) }
    : null;
  const meta = {
    slug,
    orgId: org.orgId,
    displayName: org.displayName || slugTitle + " Parks & Recreation",
    logoUrl: org.logoUrl || "",
    coords,
    locationName: active.locationName || org.campLocationName || "",
    address: active.address || org.campAddress || "",
    sites: active.sites || null,
    landmarks: active.landmarks || null,
    defaults: active.defaults || {},
    areaDefaults: active.areaDefaults || {},
    // Multi-location: the switcher list + which one is active.
    locations: locList.map(l => ({ id: l.id, name: l.locationName })),
    activeLocation: active.id || "default",
    // Editing (drag-to-place + marker editor) is unlocked only when the org
    // token is supplied and matches — admin-only; customers get the read-only view.
    canEdit: !!(org.token && req.query.token && req.query.token === org.token),
  };
  const html = fs.readFileSync(path.join(__dirname, "public", "campmap.html"), "utf-8");
  const inject = '<script>window.__CM__=' + JSON.stringify(meta) + ';</script>';
  res.type("html").send(html.replace("</head>", inject + "</head>"));
});

// Campsite map positions + custom markers.
// GET is public (viewers see the admin's saved layout); POST requires the org
// token (admin edit). Both use the same per-location store as the Camping tab.
app.get("/:org/campmap/api/positions", (req, res) => {
  const slug = req.params.org;
  if (!ORGS[slug]) return res.status(404).json({ positions: {} });
  res.json({ positions: campmapPositions[campmapStoreKey(slug, req.query.location)] || {} });
});
app.post("/:org/campmap/api/positions", express.json(), (req, res) => {
  const slug = req.params.org;
  const org = ORGS[slug];
  if (!org) return res.status(404).json({ error: "Unknown org" });
  const token = req.query.token || (req.body && req.body.token) || "";
  if (!org.token || token !== org.token) return res.status(403).json({ error: "Forbidden — valid org token required to edit." });
  const positions = (req.body && req.body.positions) || {};
  const clean = {};
  for (const [id, p] of Object.entries(positions)) {
    if (p && typeof p.lat === "number" && typeof p.lng === "number" &&
        Math.abs(p.lat) <= 90 && Math.abs(p.lng) <= 180) {
      clean[id] = { lat: p.lat, lng: p.lng };
    }
  }
  campmapPositions[campmapStoreKey(slug, req.query.location)] = clean;
  saveCampmapPositions();
  logEvent(slug, "campmap", "save-positions", req, { count: Object.keys(clean).length });
  res.json({ ok: true, saved: Object.keys(clean).length });
});
app.get("/:org/campmap/api/markers", (req, res) => {
  const slug = req.params.org;
  if (!ORGS[slug]) return res.status(404).json({ markers: [] });
  res.json({ markers: campmapMarkers[campmapStoreKey(slug, req.query.location)] || [] });
});
app.post("/:org/campmap/api/markers", express.json(), (req, res) => {
  const slug = req.params.org;
  const org = ORGS[slug];
  if (!org) return res.status(404).json({ error: "Unknown org" });
  const token = req.query.token || (req.body && req.body.token) || "";
  if (!org.token || token !== org.token) return res.status(403).json({ error: "Forbidden — valid org token required to edit." });
  const markers = (req.body && req.body.markers) || [];
  const clean = [];
  for (const m of Array.isArray(markers) ? markers : []) {
    if (!m || typeof m.lat !== "number" || typeof m.lng !== "number") continue;
    if (Math.abs(m.lat) > 90 || Math.abs(m.lng) > 180) continue;
    clean.push({
      id: String(m.id || "").slice(0, 40) || ("m" + clean.length),
      label: String(m.label || "").slice(0, 80),
      text: String(m.text || "").slice(0, 500),
      color: /^#[0-9a-fA-F]{3,8}$/.test(m.color || "") ? m.color : "#38bdf8",
      lat: m.lat, lng: m.lng,
    });
    if (clean.length >= 100) break; // sane cap
  }
  campmapMarkers[campmapStoreKey(slug, req.query.location)] = clean;
  saveCampmapMarkers();
  logEvent(slug, "campmap", "save-markers", req, { count: clean.length });
  res.json({ ok: true, saved: clean.length });
});

// Cached site data for Arsenal Park (Watertown) — fetched via rec.us MCP 2026-06-22
const RC_SITES_CACHE = {}; // Live MCP fetch for all orgs (provides rich data: photos, pricing, duration)
const rcLiveSitesCache = {}; // cacheKey -> { sites, ts }
const RC_LIVE_SITES_TTL = 60 * 60 * 1000; // 1 hour — sites rarely change
const rcPhotoCache = new Map(); // url -> { buf, type, ts }
const RC_PHOTO_TTL = 24 * 60 * 60 * 1000; // 24 hours

app.get("/:org/rentalcalendar/api/sites", async (req, res) => {
  const slug = req.params.org;
  const org = ORGS[slug];
  if (!org || !org.orgId) return res.status(404).json({ error: "Unknown org" });
  const locationId = req.query.locationId || '';
  // ?types=campsite — ask Rec for one kind of site instead of the org's whole
  // facility list. This is not an optimisation: Douglas County has 194 courts and
  // this route asked for a single page, so its 41 campsites fell off the end and
  // /douglas-county-nv/campmap got NO live data at all (no sub_type, price,
  // capacity or amenities) — loadSites() threw "no live sites matched" and the
  // page ran entirely on its baked seed. The page size below is raised for the
  // same reason.
  const VALID_TYPES = new Set(["court", "picnic-table", "room", "pool", "rink", "golf",
                               "field", "outdoor-event-space", "bounce-house", "campsite", "other", "gym"]);
  const types = String(req.query.types || '').split(',').map(t => t.trim().toLowerCase())
    .filter(t => VALID_TYPES.has(t));
  const cacheKey = org.orgId + ':' + locationId + ':' + types.join('+');
  // Check hardcoded cache first
  const orgSites = RC_SITES_CACHE[org.orgId];
  if (orgSites) {
    let sites = locationId && orgSites[locationId] ? orgSites[locationId] : Object.values(orgSites).flat();
    if (types.length) sites = sites.filter(x => types.includes(String(x.type || '').toLowerCase()));
    return res.json({ sites });
  }
  // Check live MCP response cache (1 hour TTL)
  const liveHit = rcLiveSitesCache[cacheKey];
  if (liveHit && Date.now() - liveHit.ts < RC_LIVE_SITES_TTL) {
    return res.json({ sites: liveHit.sites });
  }
  // Live fetch via MCP SDK for orgs not in cache
  try {
    const client = await getRecMcpClient();
    if (!client) throw new Error('MCP client not available');
    const result = await client.callTool({ name: 'list_sites', arguments: Object.assign(
      { organizationId: org.orgId, pageSize: 250 },
      types.length ? { siteTypes: types } : {}) });
    let sites = [];
    for (const block of (result.content || [])) {
      if (block.type === 'text' && block.text) {
        try { const p = JSON.parse(block.text); sites = p.results || p; } catch {}
      }
    }
    if (locationId) sites = sites.filter(s => s.locationId === locationId);
    const clean = sites.map(s => ({
      id: s.id, name: s.name || s.courtNumber, courtNumber: s.courtNumber,
      type: s.type, capacity: s.capacity, locationId: s.locationId,
      locationName: s.locationName, bookingUrl: s.type === 'court' ? ('https://www.rec.us/locations/' + s.locationId) : s.bookingUrl,
      bookingFlow: s.bookingFlow, isInstantBookable: s.isInstantBookable,
      description: s.description || '',
      imageUrl: (s.images && s.images.mainGallery && s.images.mainGallery[0]) ? s.images.mainGallery[0].url : null,
      gallery: (s.images && Array.isArray(s.images.mainGallery)) ? s.images.mainGallery.map(g => g && g.url).filter(Boolean) : [],
      priceCents: s.config && s.config.pricing && s.config.pricing.default ? s.config.pricing.default.cents : null,
      residentPriceCents: (() => { try { const gc = s.config.pricing.default.groupCents; const vals = Object.values(gc).filter(v => v > 0); return vals.length ? Math.min(...vals) : null; } catch(e) { return null; } })(),
      durationMinutes: s.allowedReservationDurations ? s.allowedReservationDurations.minutes : null,
      pricingType: s.config && s.config.pricing && s.config.pricing.default ? s.config.pricing.default.type : 'perHour',
      nightlyBookingPolicy: s.config && s.config.nightlyBookingPolicy ? s.config.nightlyBookingPolicy : null,
      bookingUnit: s.bookingUnit || null,
      subType: s.subType || null,
      amenities: ((s.amenities && s.amenities.amenityTagIds) || []).map(id => AMENITY_TAGS[id]).filter(Boolean),
      // The raw tag ids as well as the display names. rec.us's own amenity filter
      // takes ids — `?amenity=<uuid>,<uuid>` on the facility-rentals tab, verified
      // 2026-08-25 — and AMENITY_TAGS only covers the tags this repo has seen, so
      // mapping to names and back would silently drop anything new. The campmap
      // uses these to carry a camper's amenities into the booking hand-off.
      amenityTagIds: ((s.amenities && s.amenities.amenityTagIds) || []).filter(x => typeof x === 'string'),
      // id + name TOGETHER, and this is not redundant with the two fields above:
      // `amenities` maps through AMENITY_TAGS and then drops the misses, so a tag
      // this repo has not seen makes it SHORTER than `amenityTagIds`. Anything
      // pairing those two by index then mislabels every amenity after the first
      // unknown one — silently, and on a camper-facing page. So callers that need
      // both (the campmap's amenity filter) read this instead, where an unknown
      // tag keeps its place under a neutral label rather than vanishing.
      amenityTags: ((s.amenities && s.amenities.amenityTagIds) || [])
        .filter(x => typeof x === 'string')
        .map(id => ({ id, name: AMENITY_TAGS[id] || 'Other amenity' })),
    }));
    // Proxy photo URLs through our server for caching + Cache-Control headers
    clean.forEach(s => {
      if (s.imageUrl) s.imageUrl = '/' + slug + '/rentalcalendar/api/photo?url=' + encodeURIComponent(s.imageUrl);
      if (s.gallery && s.gallery.length) s.gallery = s.gallery.map(u => '/' + slug + '/rentalcalendar/api/photo?url=' + encodeURIComponent(u));
    });
    // Cache the MCP response for 1 hour
    rcLiveSitesCache[cacheKey] = { sites: clean, ts: Date.now() };
    res.json({ sites: clean });
  } catch (e) {
    console.error('[rentalcalendar] live sites error:', e.message);
    res.json({ sites: [], note: 'Live fetch failed: ' + e.message });
  }
});

// Photo proxy — caches remote facility images in-memory with 24h TTL + browser Cache-Control
app.get("/:org/rentalcalendar/api/photo", async (req, res) => {
  const url = req.query.url;
  if (!url) return res.status(400).end();
  // Serve from memory cache
  const cached = rcPhotoCache.get(url);
  if (cached && Date.now() - cached.ts < RC_PHOTO_TTL) {
    res.set("Cache-Control", "public, max-age=86400, immutable");
    res.set("Content-Type", cached.type);
    return res.send(cached.buf);
  }
  try {
    const resp = await fetch(url);
    if (!resp.ok) return res.status(502).end();
    const buf = Buffer.from(await resp.arrayBuffer());
    const type = resp.headers.get("content-type") || "image/jpeg";
    rcPhotoCache.set(url, { buf, type, ts: Date.now() });
    // Cap cache size — evict oldest if > 200 entries
    if (rcPhotoCache.size > 200) {
      const oldest = rcPhotoCache.keys().next().value;
      rcPhotoCache.delete(oldest);
    }
    res.set("Cache-Control", "public, max-age=86400, immutable");
    res.set("Content-Type", type);
    res.send(buf);
  } catch (e) {
    console.error("[rentalcalendar] photo proxy error:", e.message);
    res.status(502).end();
  }
});

// Availability: use MCP SDK to call rec.us MCP server directly
const rcAvailCache = {};
const RC_AVAIL_TTL = 15 * 60 * 1000; // 15 minutes
let mcpClientReady = null; // lazy-initialized promise

async function getRecMcpClient() {
  if (mcpClientReady) return mcpClientReady;
  mcpClientReady = (async () => {
    try {
      const { Client } = await import('@modelcontextprotocol/sdk/client/index.js');
      const { StreamableHTTPClientTransport } = await import('@modelcontextprotocol/sdk/client/streamableHttp.js');
      const client = new Client({ name: 'rec-rental-calendar', version: '1.0.0' });
      const transport = new StreamableHTTPClientTransport(new URL('https://api.rec.us/mcp'));
      await client.connect(transport);
      console.log('[rentalcalendar] MCP client connected (Streamable HTTP)');
      return client;
    } catch (e1) {
      console.warn('[rentalcalendar] Streamable HTTP failed:', e1.message, '— trying SSE...');
      try {
        const { Client } = await import('@modelcontextprotocol/sdk/client/index.js');
        const { SSEClientTransport } = await import('@modelcontextprotocol/sdk/client/sse.js');
        const client = new Client({ name: 'rec-rental-calendar', version: '1.0.0' });
        const transport = new SSEClientTransport(new URL('https://api.rec.us/mcp'));
        await client.connect(transport);
        console.log('[rentalcalendar] MCP client connected (SSE)');
        return client;
      } catch (e2) {
        console.error('[rentalcalendar] MCP SSE also failed:', e2.message);
        mcpClientReady = null; // allow retry
        return null;
      }
    }
  })();
  return mcpClientReady;
}

// ── Nightly availability: the 210-day feed ───────────────────────────────────
// The MCP tool `get_site_availability` hardcodes 30 days of check-in dates and
// takes no range parameter (verified three ways on 2026-08-23, public and staff
// scopes: 31 keys, today .. +30, identical). That is the TOOL's clamp, not the
// platform's horizon — rec.us's own booking page reaches months further out by
// calling the REST endpoint directly (Kevin Liu, eng, 2026-08-24):
//
//     GET /v1/sites/{siteId}/nightly-availability?from=YYYY-MM-DD&to=YYYY-MM-DD
//
// Same response shape as the MCP tool, so nothing downstream has to change:
// { data: { checkInDates: { "YYYY-MM-DD": {available, earliestCheckout,
//   latestCheckout} | {available:false, reason} } } }.
//
// Four things about this endpoint that are not guessable and cost real time to
// establish:
//
//  1. IT IS BEHIND A WAF RULE THAT 403s ANY REQUEST WITHOUT `sec-fetch-mode`.
//     The block comes from the load balancer (`server: awselb/2.0`), before the
//     app, so it looks exactly like the route not existing. Bisecting the header
//     set showed `sec-fetch-mode: cors` is the ONLY header that matters — not
//     the User-Agent, not Origin, not Referer — so we send our own honest UA
//     and that one header rather than impersonating a browser. `/v1/sites/{id}`
//     is not behind the rule, which is why the API looked reachable all along.
//  2. THE SPAN IS CAPPED AT 210 DATES, and a 211-day range is a 400 rather than
//     a truncation — so the ceiling has to be respected on the way out.
//  3. `from` MAY NOT BE IN THE PAST — AND "PAST" IS THE SITE'S LOCAL DATE, NOT
//     UTC. This one is a trap. `new Date().toISOString()` is how every other
//     route in this file computes today, and it is UTC; a Pacific campground is
//     7-8 hours behind, so from 17:00 Pacific until midnight the UTC date is
//     already TOMORROW there. Sending that as `from` silently drops the
//     campground's CURRENT NIGHT — measured 2026-08-25 00:02 UTC (17:02 PDT):
//     the MCP feed started 2026-08-24 while a UTC-dated request started
//     2026-08-25, so tonight read as `unknown` on every site. Seven hours a day
//     of a map that cannot answer "is anything free tonight", rendering
//     perfectly the whole time.
//     So we ask from YESTERDAY (UTC) and let rec.us decide: it answers 200 while
//     that is still today somewhere west of UTC, and 400s once it is genuinely
//     past. `nightlyStartDate()` probes that once and memoises for one cache
//     interval, so the fallback costs one extra request per batch rather than
//     one per site. A leading day the browser has already passed is harmless —
//     the client only reads dates inside the stay, and bookingHorizon() reads
//     the far end.
//  4. NOT EVERY CAMPSITE IS NIGHTLY. A campsite booked by the hour answers
//     `{siteUnavailable:{reason:"not-nightly"}, checkInDates:{}}` — all 12 of
//     Pleasant Hill's campsites are `bookingUnit: hourly`. That is an empty
//     answer, not an error, so it must fall through to the MCP feed rather than
//     empty the map.
//
// Every failure — WAF change, 4xx, timeout, non-nightly site — falls back to
// fetchSiteAvailability(). The extended horizon is an upgrade on top of the
// 30-day feed, never a replacement for it: the worst case is the map we had
// yesterday, not a blank one.
const MAX_NIGHTLY_SPAN_DAYS = 210;   // rec.us's own limit; 211 is a 400
const NIGHTLY_UA = 'rec-rental-report/1.0 (+https://www.rec.us)';
const rcNightlyCache = {};           // `${siteId}|${days}|${from}` -> { data, ts }

// Pure so it can be tested at a fixed instant — see scripts/campmap-nightly-window.spec.js.
// `backOne` is the answer to "is yesterday-UTC still today at the campground?".
function nightlyRange(nowMs, backOne, span) {
  const iso = ms => new Date(ms).toISOString().slice(0, 10);
  const startMs = nowMs - (backOne ? 86400000 : 0);
  return { from: iso(startMs), to: iso(startMs + (span - 1) * 86400000) };
}

// One probe, memoised for a cache interval: ask for a single day at yesterday's
// UTC date. 200 ⇒ the campground is behind UTC and that day is still bookable,
// so every request this interval starts there. 400 ⇒ it is genuinely past.
// Deliberately NOT memoised per UTC date: the answer flips mid-date (07:00 UTC,
// when Pacific catches up), so it has to expire on time rather than on the calendar.
let nightlyStartMemo = null;         // { backOne, ts }
async function nightlyStartsYesterday(probeSiteId) {
  if (nightlyStartMemo && Date.now() - nightlyStartMemo.ts < RC_AVAIL_TTL) return nightlyStartMemo.backOne;
  const d = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
  let backOne = false;
  try {
    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), 15000);
    try {
      const r = await fetch(`https://api.rec.us/v1/sites/${encodeURIComponent(probeSiteId)}`
                          + `/nightly-availability?from=${d}&to=${d}`,
        { signal: ctl.signal, headers: { 'sec-fetch-mode': 'cors', 'accept': 'application/json', 'user-agent': NIGHTLY_UA } });
      backOne = r.ok;
    } finally { clearTimeout(timer); }
  } catch (e) {
    // Unreachable probe ⇒ start from today. Losing the extra leading day is a
    // cosmetic miss; guessing that a past date is acceptable would 400 all 41.
    console.warn('[rentalcalendar] nightly start probe —', e.message);
  }
  nightlyStartMemo = { backOne, ts: Date.now() };
  return backOne;
}

async function fetchSiteNightlyAvailability(siteId, days, backOne) {
  const span = Math.max(1, Math.min(MAX_NIGHTLY_SPAN_DAYS, Number(days) || 30));
  const { from, to } = nightlyRange(Date.now(), !!backOne, span);
  const key = `${siteId}|${span}|${from}`;
  const cached = rcNightlyCache[key];
  if (cached && Date.now() - cached.ts < RC_AVAIL_TTL) return cached.data;

  const url = `https://api.rec.us/v1/sites/${encodeURIComponent(siteId)}`
            + `/nightly-availability?from=${from}&to=${to}`;
  try {
    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), 30000);
    let r;
    try {
      r = await fetch(url, {
        signal: ctl.signal,
        headers: { 'sec-fetch-mode': 'cors', 'accept': 'application/json', 'user-agent': NIGHTLY_UA },
      });
    } finally { clearTimeout(timer); }
    if (!r.ok) throw new Error('http ' + r.status);
    const body = await r.json();
    const dates = (body && body.data && body.data.checkInDates) || null;
    // An hourly site answers 200 with zero dates. Treat that as "this endpoint
    // has nothing for this site" and let the caller fall back, rather than
    // caching an empty map for 15 minutes.
    if (!dates || !Object.keys(dates).length) throw new Error('no nightly dates');
    const data = { checkInDates: dates };
    rcNightlyCache[key] = { data, ts: Date.now() };
    return data;
  } catch (e) {
    console.warn('[rentalcalendar] nightly availability', siteId, '—', e.message);
    if (cached) return cached.data;
    return null;   // null, not {} — the caller must be able to tell "no answer"
                   // from "answered, nothing free" and fall back on the first.
  }
}

async function fetchSiteAvailability(siteId) {
  const cached = rcAvailCache[siteId];
  if (cached && Date.now() - cached.ts < RC_AVAIL_TTL) return cached.data;
  try {
    const client = await getRecMcpClient();
    if (!client) throw new Error('MCP client not available');
    const result = await client.callTool({ name: 'get_site_availability', arguments: { siteId } });
    let data = {};
    for (const block of (result.content || [])) {
      if (block.type === 'text' && block.text) {
        try { const parsed = JSON.parse(block.text); data = parsed.data || parsed; } catch {}
      }
    }
    rcAvailCache[siteId] = { data, ts: Date.now() };
    console.log('[rentalcalendar] Live availability for', siteId, '(' + Object.keys(data).length + ' dates)');
    return data;
  } catch (e) {
    console.error('[rentalcalendar] availability error:', e.message);
    if (cached) return cached.data;
    return {};
  }
}

app.get("/:org/rentalcalendar/api/availability/:siteId", async (req, res) => {
  const slug = req.params.org;
  const org = ORGS[slug];
  if (!org) return res.status(404).json({ error: "Unknown org" });
  if (req.query.refresh === '1') delete rcAvailCache[req.params.siteId];
  const data = await fetchSiteAvailability(req.params.siteId);
  res.json({ data });
});

// Batch availability — fetches all sites in one request instead of 60+ individual calls.
// Processes in batches of 10 to avoid overwhelming the MCP connection.
app.get("/:org/rentalcalendar/api/availability-batch", async (req, res) => {
  const slug = req.params.org;
  const org = ORGS[slug];
  if (!org) return res.status(404).json({ error: "Unknown org" });

  const siteIds = (req.query.siteIds || '').split(',').filter(Boolean);
  if (siteIds.length === 0) return res.json({ data: {} });

  // `days` opts a caller into the 210-day nightly feed. Absent, the behaviour is
  // exactly what it was: the 30-day MCP feed. The rental calendar reads hourly
  // sites and has no use for check-in dates, so it never passes it; the campsite
  // map asks for the maximum and lets each site's own answer say where it stops.
  const days = req.query.days ? Math.max(1, Math.min(MAX_NIGHTLY_SPAN_DAYS, parseInt(req.query.days, 10) || 0)) : 0;

  const refresh = req.query.refresh === '1';
  if (refresh) {
    nightlyStartMemo = null;
    const stale = new Set(Object.keys(rcNightlyCache).filter(k => siteIds.includes(k.split('|')[0])));
    siteIds.forEach(id => { delete rcAvailCache[id]; });
    stale.forEach(k => { delete rcNightlyCache[k]; });
    console.log(`[rentalcalendar] Cache cleared for ${siteIds.length} sites (refresh=1)`);
  }

  // Which date the window starts on is a property of the ORG's timezone, not of
  // any one site, so it is settled once for the batch rather than 41 times.
  const backOne = days > 30 ? await nightlyStartsYesterday(siteIds[0]) : false;

  // Process in batches of 10 to limit concurrency against rec.us
  const BATCH_SIZE = 10;
  const data = {};
  const sources = {};
  // Per site, not per request: an org can mix nightly and hourly campsites, and
  // one hourly site must not drag the whole park back to the 30-day feed.
  const forSite = async (id) => {
    if (days > 30) {
      const nightly = await fetchSiteNightlyAvailability(id, days, backOne);
      if (nightly) return { data: nightly, source: 'nightly' };
    }
    return { data: await fetchSiteAvailability(id), source: 'mcp' };
  };
  for (let i = 0; i < siteIds.length; i += BATCH_SIZE) {
    const batch = siteIds.slice(i, i + BATCH_SIZE);
    const results = await Promise.allSettled(batch.map(forSite));
    batch.forEach((id, j) => {
      const r = results[j].status === 'fulfilled' ? results[j].value : { data: {}, source: 'none' };
      data[id] = r.data;
      sources[id] = r.source;
    });
  }

  const nightlyCount = Object.values(sources).filter(v => v === 'nightly').length;
  console.log(`[rentalcalendar] Batch availability: ${siteIds.length} sites for ${slug} (${refresh ? 'refreshed' : 'cached'}${days > 30 ? `, ${nightlyCount}/${siteIds.length} on the ${days}-day nightly feed` : ''})`);
  // `sources` is additive — the client uses it to decide whether a trailing run
  // of `outside-window` is a real booking horizon (nightly: the feed ran past the
  // site's window) or just the end of a 30-day feed (mcp: it says nothing).
  res.json({ data, sources });
});

// Reservation overlay — fetches actual bookings from Metabase facility report, strips PII.
// Returns only date/time/site/location so the public calendar can show precise reserved blocks
// without exposing reservee names, emails, phone, notes, or revenue.
const rcReservationCache = {}; // orgId:startDate:endDate -> { data, ts }
const RC_RES_TTL = 15 * 60 * 1000; // 15 minutes

app.get("/:org/rentalcalendar/api/reservations", async (req, res) => {
  const slug = req.params.org;
  const org = ORGS[slug];
  if (!org || !org.orgId) return res.status(404).json({ reservations: [] });

  const today = new Date().toISOString().slice(0, 10);
  const startDate = req.query.start_date || today;
  const endDate = req.query.end_date || new Date(Date.now() + 35 * 86400000).toISOString().slice(0, 10);

  const cacheKey = `${org.orgId}:${startDate}:${endDate}`;
  const refresh = req.query.refresh === '1';
  if (refresh) delete rcReservationCache[cacheKey];
  const cached = rcReservationCache[cacheKey];
  if (cached && Date.now() - cached.ts < RC_RES_TTL) {
    return res.json({ reservations: cached.data });
  }

  // Use shared facility UUID with org_id, or per-org fallback
  const mbUuid = SHARED_UUIDS.facility || (org.facility && org.facility.mbUuid);
  if (!mbUuid) return res.json({ reservations: [] });

  const useShared = !!SHARED_UUIDS.facility;
  const orgId = useShared ? org.orgId : null;
  const params = buildMetabaseParams({ start_date: startDate, end_date: endDate }, "facility", orgId);
  const paramStr = params.length > 0 ? `?parameters=${encodeURIComponent(JSON.stringify(params))}` : "";

  try {
    const url = `${METABASE_URL}/api/public/card/${mbUuid}/query/json${paramStr}`;
    console.log(`[rentalcalendar] reservations fetch: ${slug} ${startDate}..${endDate}`);
    const response = await fetch(url, { signal: AbortSignal.timeout(30000) });
    if (!response.ok) { console.error(`[rentalcalendar] reservations MB ${response.status}`); return res.json({ reservations: [] }); }

    const data = await response.json();

    // Strip ALL PII — return only timeline-essential fields
    const reservations = (data || []).map(row => ({
      date:     row["Date"] || row["date"] || "",
      start:    row["Start"] || row["start"] || row["Begin"] || "",
      end:      row["End"] || row["end"] || "",
      site:     row["Site/Room"] || row["Site"] || row["site"] || row["Facility"] || "",
      location: row["Location"] || row["location"] || "",
    })).filter(r => r.date && r.start && r.end && r.site);

    console.log(`[rentalcalendar] reservations: ${reservations.length} bookings for ${slug}`);
    rcReservationCache[cacheKey] = { data: reservations, ts: Date.now() };
    res.json({ reservations });
  } catch (e) {
    console.error("[rentalcalendar] reservations error:", e.message);
    res.json({ reservations: [] });
  }
});
// ── GET /:org/api/calendar-analytics — aggregate calendar funnel metrics ──
app.get("/:org/api/calendar-analytics", async (req, res) => {
  const slug = req.params.org;
  const org = ORGS[slug];
  if (!org) return res.status(404).json({ error: "Unknown org" });

  const days = parseInt(req.query.days) || 30;
  const events = readEvents(days).filter(e => e.org === slug);

  // Separate by calendar type
  const rc = events.filter(e => e.report === "rentalcalendar");
  const pc = events.filter(e => e.report === "calendar");

  // Rental calendar funnel
  const rcPageViews = rc.filter(e => e.event === "view").length;
  const rcFacViews  = rc.filter(e => e.event === "facility_view").length;
  const rcBookClicks = rc.filter(e => e.event === "book_click").length;

  // Program calendar funnel
  const pcPageViews = pc.filter(e => e.event === "view").length;
  const pcClicks    = pc.filter(e => e.event === "click").length;

  // Top facilities by views
  const facCounts = {};
  rc.filter(e => e.event === "facility_view" && e.entity).forEach(e => {
    facCounts[e.entity] = (facCounts[e.entity] || { views: 0, clicks: 0 });
    facCounts[e.entity].views++;
  });
  rc.filter(e => e.event === "book_click" && e.entity).forEach(e => {
    if (!facCounts[e.entity]) facCounts[e.entity] = { views: 0, clicks: 0 };
    facCounts[e.entity].clicks++;
  });
  const topFacilities = Object.entries(facCounts)
    .map(([name, c]) => ({ name, views: c.views, clicks: c.clicks, convPct: c.views > 0 ? Math.round(c.clicks / c.views * 100) : 0 }))
    .sort((a, b) => b.views - a.views)
    .slice(0, 10);

  // Daily breakdown for sparklines (last N days)
  const dailyMap = {};
  const now = new Date();
  for (let i = days - 1; i >= 0; i--) {
    const d = new Date(now); d.setDate(d.getDate() - i);
    dailyMap[d.toISOString().slice(0, 10)] = { rcViews: 0, rcFacViews: 0, rcClicks: 0, pcViews: 0, pcClicks: 0 };
  }
  rc.forEach(e => {
    const day = e.ts?.substring(0, 10);
    if (!dailyMap[day]) return;
    if (e.event === "view") dailyMap[day].rcViews++;
    if (e.event === "facility_view") dailyMap[day].rcFacViews++;
    if (e.event === "book_click") dailyMap[day].rcClicks++;
  });
  pc.forEach(e => {
    const day = e.ts?.substring(0, 10);
    if (!dailyMap[day]) return;
    if (e.event === "view") dailyMap[day].pcViews++;
    if (e.event === "click") dailyMap[day].pcClicks++;
  });
  const daily = Object.entries(dailyMap).sort(([a],[b]) => a.localeCompare(b))
    .map(([date, d]) => ({ date, ...d }));

  const totalViews = rcPageViews + pcPageViews;
  const totalDetailViews = rcFacViews + pcClicks;
  const totalBookClicks = rcBookClicks;
  const convPct = totalDetailViews > 0 ? Math.round(totalBookClicks / totalDetailViews * 100) : 0;

  // Bookings + revenue fetched client-side from facility data route (keeps this endpoint fast)
  res.json({
    days,
    rental: { pageViews: rcPageViews, facilityViews: rcFacViews, bookClicks: rcBookClicks, convPct: rcFacViews > 0 ? Math.round(rcBookClicks / rcFacViews * 100) : 0 },
    program: { pageViews: pcPageViews, sectionClicks: pcClicks },
    totals: { pageViews: totalViews, detailViews: totalDetailViews, bookClicks: totalBookClicks, convPct },
    topFacilities,
    daily,
  });
});

