// ── GET /api/admin/ai-analytics — AI usage metrics for dashboard ─────
app.get("/api/admin/ai-analytics", (req, res) => {
  try {
    const events = readEvents();
    const now = Date.now();
    const d7  = 7  * 86400000;
    const d30 = 30 * 86400000;

    // AI features: insights, message (chat), generate (wizard), recommend
    const aiActions = new Set(["insights", "message", "generate"]);
    const aiEvents = events.filter(e => aiActions.has(e.event) || e.report === "calendar" && e.event === "recommend");

    // By feature
    const byFeature = {};
    const byOrg = {};
    let total7d = 0, total30d = 0, totalCost7d = 0, totalCost30d = 0;
    let totalIn = 0, totalOut = 0;

    for (const e of aiEvents) {
      const age = now - new Date(e.ts).getTime();
      const feature = e.event === "insights" ? "insights"
                    : e.event === "message"  ? "chat"
                    : e.event === "generate" ? "wizard"
                    : "recommend";

      if (!byFeature[feature]) byFeature[feature] = { calls: 0, cost: 0, calls7d: 0 };
      byFeature[feature].calls++;
      byFeature[feature].cost += e.costUsd || 0;
      if (age < d7) byFeature[feature].calls7d++;

      const org = e.org || "unknown";
      if (!byOrg[org]) byOrg[org] = { calls: 0, cost: 0 };
      byOrg[org].calls++;
      byOrg[org].cost += e.costUsd || 0;

      if (age < d7)  { total7d++;  totalCost7d  += e.costUsd || 0; }
      if (age < d30) { total30d++; totalCost30d += e.costUsd || 0; }
      totalIn  += e.inTok  || 0;
      totalOut += e.outTok || 0;
    }

    // Feedback from wizard + chat votes
    const feedbackEvents = events.filter(e => e.event === "feedback" && e.vote);
    let thumbsUp = 0, thumbsDown = 0;
    feedbackEvents.forEach(e => {
      if (e.vote === "up") thumbsUp++;
      else if (e.vote === "down") thumbsDown++;
    });

    // Top 5 orgs by calls
    const topOrgs = Object.entries(byOrg)
      .sort((a, b) => b[1].calls - a[1].calls)
      .slice(0, 8)
      .map(([org, d]) => ({ org, calls: d.calls, cost: d.cost }));

    res.json({
      totalCalls: aiEvents.length,
      calls7d: total7d,
      calls30d: total30d,
      cost7d: totalCost7d,
      cost30d: totalCost30d,
      totalTokensIn: totalIn,
      totalTokensOut: totalOut,
      byFeature,
      topOrgs,
      feedback: { up: thumbsUp, down: thumbsDown },
    });
  } catch (err) {
    console.error("[ai-analytics]", err);
    res.status(500).json({ error: err.message });
  }
});

// ── Langfuse Admin — API proxy with server-side cache ────────────────
let _langfuseCache = { ts: 0, data: null };
const LANGFUSE_CACHE_TTL = 5 * 60 * 1000; // 5 minutes

async function fetchLangfuseAPI(path, params = {}) {
  if (!process.env.LANGFUSE_PUBLIC_KEY || !process.env.LANGFUSE_SECRET_KEY) return null;
  const baseUrl = process.env.LANGFUSE_BASE_URL || "https://us.cloud.langfuse.com";
  const auth = Buffer.from(process.env.LANGFUSE_PUBLIC_KEY + ":" + process.env.LANGFUSE_SECRET_KEY).toString("base64");
  const qs = new URLSearchParams(params).toString();
  const url = baseUrl + "/api/public" + path + (qs ? "?" + qs : "");
  const r = await fetch(url, { headers: { Authorization: "Basic " + auth }, signal: AbortSignal.timeout(15000) });
  if (!r.ok) { console.error("[langfuse-api]", path, r.status, await r.text().catch(() => "")); return null; }
  return r.json();
}

async function buildLangfuseAdminData() {
  const now = new Date();
  const from30d = new Date(now - 30 * 86400000).toISOString();

  // Fetch traces (last 30 days, paginated — grab up to 500)
  let allTraces = [];
  for (let page = 1; page <= 5; page++) {
    const batch = await fetchLangfuseAPI("/traces", {
      limit: 100, page, orderBy: "timestamp.desc",
      fromTimestamp: from30d,
    });
    if (!batch || !batch.data || batch.data.length === 0) break;
    allTraces = allTraces.concat(batch.data);
    if (batch.data.length < 100) break;
  }

  // Fetch scores (last 30 days, paginated — windowed to match the traces view;
  // falls back to unwindowed if the API rejects fromTimestamp)
  let allScores = [];
  let scoreParams = { limit: 100, fromTimestamp: from30d };
  let probe = await fetchLangfuseAPI("/scores", { ...scoreParams, page: 1 });
  if (!probe) { scoreParams = { limit: 100 }; probe = await fetchLangfuseAPI("/scores", { ...scoreParams, page: 1 }); }
  if (probe && probe.data && probe.data.length) {
    allScores = probe.data.slice();
    for (let page = 2; page <= 5 && allScores.length % 100 === 0; page++) {
      const batch = await fetchLangfuseAPI("/scores", { ...scoreParams, page });
      if (!batch || !batch.data || batch.data.length === 0) break;
      allScores = allScores.concat(batch.data);
      if (batch.data.length < 100) break;
    }
  }

  // Fetch daily metrics
  const dailyData = await fetchLangfuseAPI("/metrics/daily", { limit: 30 });
  const daily = dailyData?.data || [];

  // Build summary aggregates
  const d7 = 7 * 86400000;
  let totalCost = 0, cost7d = 0, totalIn = 0, totalOut = 0, traces7d = 0;
  const byFeature = {};
  const byOrg = {};

  allTraces.forEach(t => {
    const age = now - new Date(t.timestamp).getTime();
    const usage = t.usage || {};
    const cost = usage.totalCost || 0;
    totalCost += cost;
    totalIn += usage.input || usage.promptTokens || 0;
    totalOut += usage.output || usage.completionTokens || 0;
    if (age < d7) { cost7d += cost; traces7d++; }

    const feature = t.name || "unknown";
    if (!byFeature[feature]) byFeature[feature] = { traces: 0, cost: 0, up: 0, down: 0 };
    byFeature[feature].traces++;
    byFeature[feature].cost += cost;

    let org = "\u2014";
    try {
      const meta = typeof t.metadata === "string" ? JSON.parse(t.metadata) : (t.metadata || {});
      org = meta.org || meta["rec.org"] || "\u2014";
    } catch {}
    if (!byOrg[org]) byOrg[org] = { traces: 0, cost: 0, up: 0, down: 0 };
    byOrg[org].traces++;
    byOrg[org].cost += cost;
  });

  // Map scores to features/orgs
  const traceMap = {};
  allTraces.forEach(t => { traceMap[t.id] = t; });
  let thumbsUp = 0, thumbsDown = 0;
  allScores.forEach(s => {
    if (s.value >= 1) thumbsUp++; else thumbsDown++;
    const trace = traceMap[s.traceId];
    if (trace) {
      const feature = trace.name || "unknown";
      if (byFeature[feature]) { if (s.value >= 1) byFeature[feature].up++; else byFeature[feature].down++; }
      let org = "\u2014";
      try {
        const meta = typeof trace.metadata === "string" ? JSON.parse(trace.metadata) : (trace.metadata || {});
        org = meta.org || meta["rec.org"] || "\u2014";
      } catch {}
      if (byOrg[org]) { if (s.value >= 1) byOrg[org].up++; else byOrg[org].down++; }
    }
  });

  return {
    traces: allTraces,
    scores: allScores,
    daily,
    summary: {
      totalTraces: allTraces.length,
      traces7d,
      totalScores: allScores.length,
      thumbsUp, thumbsDown,
      totalCost, cost7d,
      totalTokensIn: totalIn,
      totalTokensOut: totalOut,
      byFeature, byOrg,
    },
    cachedAt: new Date().toISOString(),
  };
}

app.get("/api/admin/langfuse", async (req, res) => {
  try {
    if (!process.env.LANGFUSE_PUBLIC_KEY || !process.env.LANGFUSE_SECRET_KEY) {
      return res.status(503).json({ error: "Langfuse not configured" });
    }
    const forceRefresh = req.query.refresh === "1";
    if (!forceRefresh && _langfuseCache.data && (Date.now() - _langfuseCache.ts < LANGFUSE_CACHE_TTL)) {
      return res.json(_langfuseCache.data);
    }
    console.log("[langfuse-admin] Fetching fresh data from Langfuse API...");
    const data = await buildLangfuseAdminData();
    _langfuseCache = { ts: Date.now(), data };
    console.log("[langfuse-admin] Cached:", data.traces.length, "traces,", data.scores.length, "scores");
    res.json(data);
  } catch (err) {
    console.error("[langfuse-admin]", err);
    res.status(500).json({ error: err.message });
  }
});

// ── POST /api/admin/langfuse/reset — password-gated cache clear ──────
app.post("/api/admin/langfuse/reset", (req, res) => {
  const pw = req.body?.password;
  if (!pw || pw !== process.env.DASHBOARD_PASSWORD) {
    return res.status(403).json({ error: "Invalid password" });
  }
  _langfuseCache = { ts: 0, data: null };
  console.log("[langfuse-admin] Cache reset by admin");
  res.json({ ok: true });
});

// ── POST /api/admin/langfuse/purge — permanently DELETE traces + scores ──
// Password-gated + scoped. mode:"all" wipes everything; mode:"before" deletes
// items with timestamp < `before` (ISO date). Clearing the cache alone can't
// remove test data — it lives in Langfuse, so this deletes it via the API.
// Scores are independent objects in Langfuse: the batch trace delete does NOT
// cascade to them, and there is no bulk score delete — each one is deleted
// individually via DELETE /api/public/scores/{id}.
app.post("/api/admin/langfuse/purge", async (req, res) => {
  const { password, mode, before } = req.body || {};
  if (!password || password !== process.env.DASHBOARD_PASSWORD) {
    return res.status(403).json({ error: "Invalid password" });
  }
  if (!process.env.LANGFUSE_PUBLIC_KEY || !process.env.LANGFUSE_SECRET_KEY) {
    return res.status(503).json({ error: "Langfuse not configured" });
  }
  const beforeTs = (mode === "before" && before) ? new Date(before).toISOString() : null;
  try {
    // Collect trace IDs to delete (all, or only those before the cutoff)
    let ids = [];
    for (let page = 1; page <= 60; page++) { // safety cap ~6000 traces
      const params = { limit: 100, page, orderBy: "timestamp.desc" };
      if (beforeTs) params.toTimestamp = beforeTs; // upper bound
      const batch = await fetchLangfuseAPI("/traces", params);
      if (!batch || !batch.data || !batch.data.length) break;
      ids = ids.concat(batch.data.map(t => t.id));
      if (batch.data.length < 100) break;
    }

    // Collect score IDs (scores survive trace deletion, so purge them even
    // when no traces remain). Cutoff filtered client-side — the scores list
    // endpoint has no toTimestamp param.
    let scoreIds = [];
    for (let page = 1; page <= 20; page++) { // safety cap ~2000 scores
      const batch = await fetchLangfuseAPI("/scores", { limit: 100, page });
      if (!batch || !batch.data || !batch.data.length) break;
      const eligible = beforeTs
        ? batch.data.filter(s => s.timestamp && s.timestamp < beforeTs)
        : batch.data;
      scoreIds = scoreIds.concat(eligible.map(s => s.id).filter(Boolean));
      if (batch.data.length < 100) break;
    }

    if (!ids.length && !scoreIds.length) {
      _langfuseCache = { ts: 0, data: null };
      return res.json({ ok: true, deleted: 0, requested: 0, scoresDeleted: 0, scoresRequested: 0 });
    }

    const baseUrl = process.env.LANGFUSE_BASE_URL || "https://us.cloud.langfuse.com";
    const auth = Buffer.from(process.env.LANGFUSE_PUBLIC_KEY + ":" + process.env.LANGFUSE_SECRET_KEY).toString("base64");

    // Batch-delete traces (DELETE /api/public/traces {traceIds})
    let deleted = 0;
    for (let i = 0; i < ids.length; i += 100) {
      const chunk = ids.slice(i, i + 100);
      const r = await fetch(baseUrl + "/api/public/traces", {
        method: "DELETE",
        headers: { "Content-Type": "application/json", "Authorization": "Basic " + auth },
        body: JSON.stringify({ traceIds: chunk }),
        signal: AbortSignal.timeout(30000),
      });
      if (r.ok) deleted += chunk.length;
      else console.error("[langfuse-admin] purge chunk failed:", r.status, await r.text().catch(() => ""));
    }

    // Delete scores one-by-one, small concurrency
    let scoresDeleted = 0;
    for (let i = 0; i < scoreIds.length; i += 5) {
      const chunk = scoreIds.slice(i, i + 5);
      const results = await Promise.allSettled(chunk.map(id =>
        fetch(baseUrl + "/api/public/scores/" + encodeURIComponent(id), {
          method: "DELETE",
          headers: { "Authorization": "Basic " + auth },
          signal: AbortSignal.timeout(15000),
        })
      ));
      results.forEach((r, j) => {
        if (r.status === "fulfilled" && r.value.ok) scoresDeleted++;
        else console.error("[langfuse-admin] score delete failed:", chunk[j], r.status === "fulfilled" ? r.value.status : r.reason?.message);
      });
    }

    _langfuseCache = { ts: 0, data: null };
    console.log("[langfuse-admin] Purged " + deleted + "/" + ids.length + " traces, " + scoresDeleted + "/" + scoreIds.length + " scores (mode=" + (mode || "all") + (beforeTs ? " before " + beforeTs : "") + ")");
    res.json({ ok: true, deleted, requested: ids.length, scoresDeleted, scoresRequested: scoreIds.length });
  } catch (e) {
    console.error("[langfuse-admin] purge error:", e.message);
    res.status(500).json({ error: e.message });
  }
});

